    ("body", "M60,93 C10,90 -50,92 -90,97"), ("body", "M140,93 C190,90 250,92 290,97"),
    ("body", "M74,262 C68,320 64,385 58,444"), ("body", "M126,262 C132,320 136,385 142,444"),
    ("bodycircle", 100, 38, 26),
