VIEWBOX = (-140, -20, 480, 500)


def svg_path_points(d, steps=10):
    """SVG path (absolute M/L/C/Q/Z) -> list of polylines [(x,y),...]."""
    tokens = re.findall(r"[MLCQZ]|-?\d*\.?\d+", d)
    polys, cur, pos, start = [], [], (0.0, 0.0), (0.0, 0.0)
    i = 0

    def nums(n):
        nonlocal i
        vals = [float(tokens[i + k]) for k in range(n)]
        i += n
        return vals

    while i < len(tokens):
        t = tokens[i]
        i += 1
        if t == "M":
            if len(cur) > 1:
                polys.append(cur)
            x, y = nums(2)
            pos = start = (x, y)
            cur = [pos]
        elif t == "L":
            x, y = nums(2)
            pos = (x, y)
            cur.append(pos)
        elif t == "C":
            x1, y1, x2, y2, x, y = nums(6)
            x0, y0 = pos
            for k in range(1, steps + 1):
                u = k / steps
                cur.append((
                    (1 - u) ** 3 * x0 + 3 * (1 - u) ** 2 * u * x1 + 3 * (1 - u) * u * u * x2 + u ** 3 * x,
                    (1 - u) ** 3 * y0 + 3 * (1 - u) ** 2 * u * y1 + 3 * (1 - u) * u * u * y2 + u ** 3 * y))
            pos = (x, y)
        elif t == "Q":
            x1, y1, x, y = nums(4)
            x0, y0 = pos
            for k in range(1, steps + 1):
                u = k / steps
                cur.append(((1 - u) ** 2 * x0 + 2 * (1 - u) * u * x1 + u * u * x,
                            (1 - u) ** 2 * y0 + 2 * (1 - u) * u * y1 + u * u * y))
            pos = (x, y)
        elif t == "Z":
            cur.append(start)
            pos = start
    if len(cur) > 1:
        polys.append(cur)
    return polys


def ellipse_points(cx, cy, rx, ry, angle=0, n=24):
    import math
    a = math.radians(angle)
    out = []
    for k in range(n):
        t = 2 * math.pi * k / n
        x, y = rx * math.cos(t), ry * math.sin(t)
        out.append((cx + x * math.cos(a) - y * math.sin(a), cy + x * math.sin(a) + y * math.cos(a)))
    return out


class BodyMap:
    """The Vitruvian figure on the measurement card. One marker per system
    present in the corpus; a click filters the list by that system; the plate
    of the open measurement's system is drawn over the outline."""

    def __init__(self, app, parent, pad, height=360):
        self.app = app
        self.height = height
        self.scale = height / VIEWBOX[3]
        self.width = int(VIEWBOX[2] * self.scale)
        self.current = None          # highlighted system
        self.hot = None
        self.hits = []               # (x, y, system)
        self.toggle = tk.Label(parent, text="", bg=PAPER, fg=FAINT, font=app.f_label,
                               anchor="w", cursor="hand2")
        self.toggle.pack(fill="x", pady=(6, 0), **pad)
        self.toggle.bind("<Button-1>", lambda e: self.set_open(not self.open))
        self.wrap = tk.Frame(parent, bg=PAPER)
        self.pad = pad
        self.cv = tk.Canvas(self.wrap, height=height, width=self.width, bg=PAPER,
                            highlightthickness=0, bd=0)
        self.cv.pack(side="left")
        self.legend = tk.Frame(self.wrap, bg=PAPER)
        self.legend.pack(side="left", fill="both", expand=True, padx=(16, 0))
        self.open = bool((app.data.get("ui") or {}).get("map_open", True))
        self.set_open(self.open, save=False)
        self.cv.bind("<Button-1>", self.clicked)
        self.cv.bind("<Motion>", self.moved)
        self.cv.bind("<Leave>", lambda e: self.cv.configure(cursor=""))
        tk.Frame(parent, bg=RULE, height=1).pack(fill="x", pady=(6, 0), **pad)

    def set_open(self, on, save=True):
        self.open = on
        self.toggle.configure(text=("[−] " if on else "[+] ") + tr("body map"))
        if on:
            self.wrap.pack(fill="x", after=self.toggle, **self.pad)
            self.redraw()
        else:
            self.wrap.pack_forget()
        if save:
            self.app.save_prefs({"map_open": on})

    # ---- geometry
    def P(self, x, y):
        return ((x - VIEWBOX[0]) * self.scale, (y - VIEWBOX[1]) * self.scale)

    def flat(self, pts):
        out = []
        for x, y in pts:
            out.extend(self.P(x, y))
        return out

    def draw_prims(self, prims, color, width=1.0, dash=None):
        cv = self.cv
        for prim in prims:
            kind = prim[0]
            if kind in ("path", "echo", "body"):
                for poly in svg_path_points(prim[1]):
                    cv.create_line(*self.flat(poly), fill=color, width=width, dash=dash,
                                   joinstyle="round", capstyle="round")
            elif kind == "organ":
                for poly in svg_path_points(prim[1]):
                    cv.create_polygon(*self.flat(poly), outline=color, fill=color,
                                      stipple="gray12", width=width)
            elif kind in ("circle", "bodycircle"):
                _, cx, cy, r = prim
                x0, y0 = self.P(cx - r, cy - r)
                x1, y1 = self.P(cx + r, cy + r)
                cv.create_oval(x0, y0, x1, y1, outline=color, width=width, fill=PAPER
                               if kind == "circle" and r <= 3 else "")
            elif kind == "ellipse":
                _, cx, cy, rx, ry, ang = prim
                cv.create_polygon(*self.flat(ellipse_points(cx, cy, rx, ry, ang)),
                                  outline=color, fill=color, stipple="gray12", width=width)
            elif kind == "line":
                _, x1, y1, x2, y2, d = prim
                cv.create_line(*self.P(x1, y1), *self.P(x2, y2), fill=color, width=width,
                               dash=d, capstyle="round")
            elif kind == "rect":
                _, x, y, w, h = prim
                cv.create_rectangle(*self.P(x, y), *self.P(x + w, y + h), outline=color,
                                    width=width)

    # ---- data
    def systems(self):
        """{system: (n measurements, any out of range?)}"""
        out = {}
        for m in self.app.data.get("corpus", []):
            s = m.get("system") or "outro"
            n, bad = out.get(s, (0, False))
            lr = last_reading(m)
            out[s] = (n + 1, bad or bool(lr and out_of_range(m, lr)))
        return out

    def redraw(self):
        cv = self.cv
        if not cv.winfo_exists() or not self.open:
            return
        cv.delete("all")
        self.hits = []
        # the frame in a faded tone, the open pose dashed, the body in a line
        self.draw_prims([p for p in FIGURE if p[0] in ("rect", "circle")], RULE, 1.0)
        self.draw_prims([p for p in FIGURE if p[0] == "echo"], FAINT, 1.0, (3, 3))
        self.draw_prims([p for p in FIGURE if p[0] in ("body", "bodycircle")], SOFT, 1.4)
        systems = self.systems()
        # plate of the highlighted system
        plate = PLATE_OF.get(self.current or "")
        if plate in PLATES:
            self.draw_prims(PLATES[plate], INK, 1.2)
        # markers: one square per system present, shifted if the plate is shared;
        # filled when the latest reading is out of range
        used, unplaced = {}, 0
        for sname in sorted(systems, key=sort_key):
            n, bad = systems[sname]
            pl = PLATE_OF.get(sname)
            if pl in MARKER_OF:
                x, y = MARKER_OF[pl]
                k = used.get(pl, 0)
                used[pl] = k + 1
                x += 16 * k
            else:
                x, y = -110, 450 + unplaced * 16
                unplaced += 1
            px, py = self.P(x, y)
            half = 5 if sname == self.current else 3.5
            cv.create_rectangle(px - half, py - half, px + half, py + half,
                                outline=INK, width=1.6 if sname == self.current else 1.2,
                                fill=INK if bad else PAPER)
            for a, b, c, d in ((px - half - 3, py, px - half, py), (px + half, py, px + half + 3, py),
                               (px, py - half - 3, px, py - half), (px, py + half, px, py + half + 3)):
                cv.create_line(a, b, c, d, fill=INK)
            if pl not in MARKER_OF:
                cv.create_text(px + 10, py, text=system_label(sname), anchor="w", fill=FAINT,
                               font=self.app.f_label)
            self.hits.append((px, py, sname))
        # legend
        ui = self.app.data.get("ui") or {}
        subject = ui.get("corpus_subject") or ""
        cv.create_text(6, 6, text=("corpus · " + subject) if subject else "corpus",
                       anchor="nw", fill=FAINT, font=self.app.f_label)
        for w in self.legend.winfo_children():
            w.destroy()
        tk.Label(self.legend, text=tr("SYSTEMS"), bg=PAPER, fg=FAINT, font=self.app.f_label,
                 anchor="w").pack(fill="x", pady=(2, 4))
        if not systems:
            tk.Label(self.legend, text=tr("no measurements yet"), bg=PAPER, fg=FAINT,
                     font=self.app.f_meta, anchor="w").pack(fill="x")
        for sname in sorted(systems, key=sort_key):
            n, bad = systems[sname]
            on = sname == self.current
            mark = "[x]" if on else "[ ]"
            row = tk.Label(self.legend, text=f"{mark} {system_label(sname)}  {n}"
                           + ("  (!)" if bad else ""),
                           bg=PAPER, fg=INK if on else SOFT, font=self.app.f_meta,
                           anchor="w", cursor="hand2")
            row.pack(fill="x")
            row.bind("<Button-1>", lambda e, s=sname: self.pick(s))
        tk.Label(self.legend, text=tr("a click filters the list; (!) out of range"),
                 bg=PAPER, fg=FAINT, font=self.app.f_label, anchor="w",
                 justify="left").pack(fill="x", pady=(8, 0))

    def hit(self, x, y):
        for px, py, s in self.hits:
            if abs(x - px) <= 9 and abs(y - py) <= 9:
                return s
        return None

    def moved(self, e):
        s = self.hit(e.x, e.y)
        if s != self.hot:
            self.hot = s
            self.cv.configure(cursor="hand2" if s else "")

    def clicked(self, e):
        s = self.hit(e.x, e.y)
        if s:
            self.pick(s)

    def pick(self, sname):
        self.app.filter_system(sname)

    def set_current(self, sname):
        self.current = sname
        self.redraw()


class SourceCard:
    """The source card: the type's fields, and the citation ready to copy."""

    def __init__(self, app, parent):
        self.app = app
        self.frame = tk.Frame(parent, bg=PAPER)
        self.stype = "outro"
        self.in_ids, self.out_ids, self.use_ids = [], [], []
        self.build()

    def build(self):
        app, shell = self.app, self.frame
        pad = dict(padx=22)
        foot = tk.Frame(shell, bg=PAPER)
        foot.pack(fill="x", side="bottom", pady=12, **pad)
        ttk.Button(foot, text=tr("Save"), command=app.save).pack(side="left")
        ttk.Button(foot, text=tr("Save and new"), style="Quiet.TButton",
                   command=app.save_and_new).pack(side="left", padx=(8, 0))
        self.msg = tk.Label(foot, text="", bg=PAPER, fg=OXIDE, font=app.f_meta)
        self.msg.pack(side="left", padx=14)
        ttk.Button(foot, text=tr("Delete"), style="Quiet.TButton",
                   command=app.delete).pack(side="right")
        tk.Frame(shell, bg=RULE, height=1).pack(fill="x", side="bottom")

        c = app.scroll_area(shell)
        head = tk.Frame(c, bg=PAPER)
        head.pack(fill="x", pady=(11, 0), **pad)
        self.e_name = tk.Entry(head, width=1, font=app.f_name, bg=PAPER, fg=INK,
                               relief="flat", insertbackground=INK, insertwidth=2,
                               highlightthickness=0, disabledbackground=PAPER,
                               disabledforeground=FAINT)
        self.e_name.pack(side="left", fill="x", expand=True)
        self.stamp = tk.Label(head, text="", bg=PAPER, fg=FAINT, font=app.f_meta,
                              justify="right")
        self.stamp.pack(side="right")
        tk.Frame(c, bg=STAMP, height=2).pack(fill="x", pady=(6, 0), **pad)

        # type: an editable combobox -- the list suggests, you decide
        trow = tk.Frame(c, bg=PAPER)
        trow.pack(fill="x", **pad)
        tcol = tk.Frame(trow, bg=PAPER)
        tcol.pack(side="left")
        tk.Label(tcol, text=tr("TYPE"), bg=PAPER, fg=FAINT, font=app.f_label,
                 anchor="w").pack(fill="x", pady=(8, 2))
        self.v_type = tk.StringVar(value=type_label("outro"))
        self.e_type = ttk.Combobox(tcol, textvariable=self.v_type,
                                   values=[type_label(t) for t in SOURCE_TYPES],
                                   width=18, font=app.f_meta)
        self.e_type.pack(anchor="w")
        self.e_type.bind("<<ComboboxSelected>>", self.type_changed)
        self.e_type.bind("<KeyRelease>", self.type_changed)
        tk.Label(trow, text="  " + tr("changing the type only changes the visible fields; "
                                      "nothing is lost"),
                 bg=PAPER, fg=FAINT, font=app.f_label).pack(side="left", pady=(22, 0))

        self.blocks = {}
        self.widgets = {}

        def block(fid):
            f = tk.Frame(c, bg=PAPER)
            self.blocks[fid] = f
            return f

        label = lambda fid: tr(SOURCE_FIELD_LABEL[fid])
        self.widgets["authors"] = app.textfield(block("authors"), label("authors"),
                                                2, app.f_meta, pad)
        self.widgets["date"] = app.field(block("date"), label("date"), app.f_meta, pad)
        self.widgets["container"] = app.field(block("container"), label("container"),
                                              app.f_body, pad)
        self.widgets["publisher"] = app.field(block("publisher"), label("publisher"),
                                              app.f_meta, pad)
        self.widgets["place"] = app.field(block("place"), label("place"), app.f_meta, pad)
        # edition · volume · issue · pages on a single row
        row = block("numbers")
        for fid in ("edition", "volume", "issue", "pages"):
            col = tk.Frame(row, bg=PAPER)
            col.pack(side="left", fill="x", expand=True, padx=(0, 10))
            tk.Label(col, text=label(fid), bg=PAPER, fg=FAINT, font=app.f_label,
                     anchor="w").pack(fill="x", pady=(8, 2))
            ent = tk.Entry(col, width=8, font=app.f_meta, bg=PAPER, fg=INK,
                           insertbackground=INK, relief="flat", highlightthickness=0,
                           disabledbackground=PAPER, disabledforeground=FAINT)
            ent.pack(fill="x")
            tk.Frame(col, bg=RULE, height=1).pack(fill="x", pady=(4, 0))
            app.bind_undo(ent)
            self.widgets[fid] = ent
        row2 = block("ids")
        for fid in ("doi", "isbn", "accessed", "lang"):
            col = tk.Frame(row2, bg=PAPER)
            col.pack(side="left", fill="x", expand=True, padx=(0, 10))
            tk.Label(col, text=label(fid), bg=PAPER, fg=FAINT, font=app.f_label,
                     anchor="w").pack(fill="x", pady=(8, 2))
            ent = tk.Entry(col, width=10, font=app.f_meta, bg=PAPER, fg=INK,
                           insertbackground=INK, relief="flat", highlightthickness=0,
                           disabledbackground=PAPER, disabledforeground=FAINT)
            ent.pack(fill="x")
            tk.Frame(col, bg=RULE, height=1).pack(fill="x", pady=(4, 0))
            app.bind_undo(ent)
            self.widgets[fid] = ent
        self.widgets["url"] = app.field(block("url"), label("url"), app.f_meta, pad)
        self.widgets["extra"] = app.textfield(block("extra"), label("extra"), 2,
                                              app.f_meta, pad)
        self.e_tags = app.field(block("tags"), tr("TAGS"), app.f_meta, pad)
        self.t_notes = app.textfield(block("notes"), tr("NOTES"), 3, app.f_body, pad,
                                     pages=True)
        self.t_geo = app.geo_field(block("geo"), pad)

        b = block("cite")
        crow = tk.Frame(b, bg=PAPER)
        crow.pack(fill="x", pady=(6, 2), **pad)
        tk.Label(crow, text=tr("CITATION"), bg=PAPER, fg=FAINT, font=app.f_label,
                 anchor="w").pack(side="left")
        self.v_style = tk.StringVar(value=(app.data.get("ui") or {}).get("cite_style", "abnt"))
        sb = ttk.Combobox(crow, textvariable=self.v_style, values=list(CITE_STYLES),
                          state="readonly", width=15, font=app.f_meta)
        sb.pack(side="left", padx=(10, 0))
        sb.bind("<<ComboboxSelected>>", lambda e: self.refresh_cite())
        ttk.Button(crow, text=tr("copy"), style="Quiet.TButton",
                   command=self.copy_cite).pack(side="left", padx=(8, 0))
        self.t_cite = tk.Text(b, height=3, width=1, font=app.f_meta, bg=SHELL, fg=INK,
                              relief="flat", wrap="word", highlightthickness=0,
                              padx=8, pady=6)
        self.t_cite.pack(fill="x", **pad)
        app.autogrow(self.t_cite, minrows=2)

        b = block("edges")
        app.label(b, tr("LINKS  (rel  target  [span]  [@circle]  — reason  # source)"), pad)
        self.t_edges = tk.Text(b, height=2, width=1, font=app.f_meta, bg=PAPER, fg=INK,
                               insertbackground=INK, relief="flat", wrap="word",
                               highlightthickness=0, padx=0, spacing1=1, spacing3=3,
                               undo=True, autoseparators=True, maxundo=-1)
        app.block_caret(self.t_edges, app.f_meta)
        app.bind_undo(self.t_edges, text=True)
        self.t_edges.pack(fill="x", **pad)
        app.autogrow(self.t_edges, minrows=2)
        tk.Frame(b, bg=RULE, height=1).pack(fill="x", pady=(4, 0), **pad)

        b = block("out")
        app.label(b, tr("RESOLVED LINKS  (double-click opens)"), pad)
        self.outbox = app.listbox(b, pad)
        self.outbox.bind("<Double-Button-1>", lambda e: app.jump(self.outbox, self.out_ids))
        b = block("inb")
        app.label(b, tr("CITED BY  (double-click opens)"), pad)
        self.inbox = app.listbox(b, pad)
        self.inbox.bind("<Double-Button-1>", lambda e: app.jump(self.inbox, self.in_ids))
        b = block("uses")
        app.label(b, tr("SOURCE OF  (records whose SOURCE field points here; double-click opens)"), pad)
        self.usebox = app.listbox(b, pad)
        self.usebox.bind("<Double-Button-1>", lambda e: app.jump(self.usebox, self.use_ids))
        self.t_links = app.textfield(block("links"), tr("URLS"), 2, app.f_meta, pad)
        self.tail = tk.Frame(c, bg=PAPER, height=12)

        self.entries = [self.e_name, self.e_tags] + [w for k, w in self.widgets.items()
                                                       if k not in ("authors", "extra")]
        self.texts = [self.widgets["authors"], self.widgets["extra"], self.t_notes,
                      self.t_edges, self.t_links, self.t_geo]
        app.bind_undo(self.e_name)
        for w in self.entries + self.texts:
            for ev in ("<KeyRelease>", "<<Paste>>", "<<Cut>>"):
                w.bind(ev, app.mark_dirty, add="+")
                w.bind(ev, lambda e: self.app.root.after(300, self.refresh_cite), add="+")
        self.apply_layout()

    ORDER = ["authors", "date", "container", "publisher", "place", "numbers", "ids",
             "url", "extra", "tags", "notes", "geo", "cite", "edges", "out", "inb", "uses", "links"]

    def apply_layout(self):
        show = set(source_fields_for(self.stype))
        for f in self.blocks.values():
            f.pack_forget()
        self.tail.pack_forget()
        for fid in self.ORDER:
            if fid == "numbers" and not show & {"edition", "volume", "issue", "pages"}:
                continue
            if fid == "ids" and not show & {"doi", "isbn", "accessed", "lang"}:
                continue
            if fid in SOURCE_FIELD_LABEL and fid not in show:
                continue
            self.blocks[fid].pack(fill="x", padx=22 if fid in ("numbers", "ids") else 0)
        self.tail.pack(fill="x")

    def type_changed(self, _e=None):
        self.stype = type_key(self.v_type.get()) or "outro"
        self.apply_layout()
        self.app.mark_dirty()
        self.refresh_cite()

    def enable(self, on):
        state = "normal" if on else "disabled"
        for w in self.entries + self.texts:
            w.configure(state=state)
        self.e_type.configure(state="normal" if on else "disabled")

    def clear(self):
        for w in self.entries:
            w.delete(0, "end")
        for t in self.texts:
            t.delete("1.0", "end")
        for lb in (self.outbox, self.inbox, self.usebox):
            lb.delete(0, "end")
        self.app.update_geo_hint(self.t_geo)
        self.t_cite.configure(state="normal")
        self.t_cite.delete("1.0", "end")
        self.t_cite.configure(state="disabled")
        self.stamp.configure(text="")
        self.msg.configure(text="")

    def open(self, s):
        self.enable(True)
        self.stype = (s.get("type") or "outro").lower()
        self.v_type.set(type_label(s.get("type") or "outro"))
        self.e_name.delete(0, "end")
        self.e_name.insert(0, s.get("name", ""))
        for k, w in self.widgets.items():
            if k in ("authors", "extra"):
                w.delete("1.0", "end")
                w.insert("1.0", "\n".join(s.get(k, [])))
            else:
                w.delete(0, "end")
                w.insert(0, s.get(k, ""))
        self.e_tags.delete(0, "end")
        self.e_tags.insert(0, ", ".join(s.get("tags", [])))
        self.t_notes.delete("1.0", "end")
        self.t_notes.insert("1.0", s.get("notes", ""))
        self.app.geo_put(self.t_geo, s.get("geo", ""))
        self.t_links.delete("1.0", "end")
        self.t_links.insert("1.0", "\n".join(s.get("links", [])))
        self.t_edges.delete("1.0", "end")
        text = format_edges(edges_from(self.app.data, s["id"]))
        if s.get("edge_drafts"):
            text = "\n".join(filter(None, [text] + s["edge_drafts"]))
        self.t_edges.insert("1.0", text)
        rid = s["id"] if not s["id"].startswith("__") else tr("draft")
        self.stamp.configure(text=f"{rid}\n{s.get('updated', '')}"
                             + ("\n" + tr("[raw text kept]") if s.get("raw") else ""))
        self.msg.configure(text="")
        self.apply_layout()
        self.refresh_neighbours(s["id"])
        self.refresh_cite()

    def refresh_neighbours(self, sid):
        app = self.app
        data, idx = app.data, by_id(app.data)
        self.outbox.delete(0, "end")
        self.out_ids = []
        for a in edges_from(data, sid):
            target = idx.get(a["to"])
            shown = label_any(target, data) if target else tr("{id}  (missing target)", id=a["to"])
            self.outbox.insert("end", f"{link_rel_text(a):18} {shown}")
            self.out_ids.append(a["to"])
        self.inbox.delete(0, "end")
        self.in_ids = []
        for a in edges_to(data, sid):
            src = idx.get(a["from"])
            self.inbox.insert("end", f"{label_any(src, data):30} {link_rel_text(a)}")
            self.in_ids.append(a["from"])
        self.usebox.delete(0, "end")
        self.use_ids = []
        for coll in ("people", "entries", "corpus"):
            for r in data[coll]:
                if r.get("source") == sid:
                    self.usebox.insert("end", f"{tr(COLL_LABEL[coll]):8} {label_any(r, data)}")
                    self.use_ids.append(r["id"])
        for lb in (self.outbox, self.inbox, self.usebox):
            lb.configure(height=max(2, min(10, lb.size())))

    def gather(self, s):
        out = {k: v for k, v in s.items() if not k.startswith("_")}
        out["type"] = type_key(self.v_type.get()) or "outro"
        out["name"] = self.e_name.get().strip()
        for k, w in self.widgets.items():
            if k in ("authors", "extra"):
                out[k] = [l.strip() for l in w.get("1.0", "end-1c").splitlines() if l.strip()]
            else:
                out[k] = w.get().strip()
        out["tags"] = [t.strip() for t in self.e_tags.get().split(",") if t.strip()]
        out["notes"] = self.t_notes.get("1.0", "end-1c").strip()
        out["geo"] = self.t_geo.get("1.0", "end-1c").strip()
        out["links"] = [l.strip() for l in self.t_links.get("1.0", "end-1c").splitlines()
                        if l.strip()]
        return out

    def edges_text(self):
        return self.t_edges.get("1.0", "end-1c")

    def refresh_cite(self):
        if self.app.shown != "source" or not self.app.sel:
            return
        try:
            s = self.gather(self.app.current() or {})
            text = cite(s, self.v_style.get(), self.app.data)
        except Exception as err:      # the citation must never bring the card down
            text = tr("(could not build the citation: {err})", err=err)
        self.t_cite.configure(state="normal")
        self.t_cite.delete("1.0", "end")
        self.t_cite.insert("1.0", text)
        self.t_cite.configure(state="disabled")

    def copy_cite(self):
        text = self.t_cite.get("1.0", "end-1c")
        self.app.root.clipboard_clear()
        self.app.root.clipboard_append(text)
        save_ui({"cite_style": self.v_style.get()})
        self.msg.configure(text=tr("Citation copied."))


class MetricCard:
    """The health card. Its fields follow the record's type: a measurement
    (unit, reference range, readings over time), a medication (dose,
    frequency, since/until, prescriber), an activity or habit (aim, sessions)
    or an event (kind, date, doctor, place)."""

    def __init__(self, app, parent):
        self.app = app
        self.frame = tk.Frame(parent, bg=PAPER)
        self.in_ids, self.out_ids = [], []
        self.build()

    def build(self):
        app, shell = self.app, self.frame
        pad = dict(padx=22)
        foot = tk.Frame(shell, bg=PAPER)
        foot.pack(fill="x", side="bottom", pady=12, **pad)
        ttk.Button(foot, text=tr("Save"), command=app.save).pack(side="left")
        ttk.Button(foot, text=tr("Save and new"), style="Quiet.TButton",
                   command=app.save_and_new).pack(side="left", padx=(8, 0))
        ttk.Button(foot, text=tr("body map"), style="Quiet.TButton",
                   command=app.do_corpus).pack(side="left", padx=(8, 0))
        ttk.Button(foot, text=tr("report"), style="Quiet.TButton",
                   command=app.do_health).pack(side="left", padx=(8, 0))
        self.msg = tk.Label(foot, text="", bg=PAPER, fg=OXIDE, font=app.f_meta)
        self.msg.pack(side="left", padx=14)
        ttk.Button(foot, text=tr("Delete"), style="Quiet.TButton",
                   command=app.delete).pack(side="right")
        tk.Frame(shell, bg=RULE, height=1).pack(fill="x", side="bottom")

        c = app.scroll_area(shell)
        head = tk.Frame(c, bg=PAPER)
        head.pack(fill="x", pady=(11, 0), **pad)
        self.e_name = tk.Entry(head, width=1, font=app.f_name, bg=PAPER, fg=INK,
                               relief="flat", insertbackground=INK, insertwidth=2,
                               highlightthickness=0, disabledbackground=PAPER,
                               disabledforeground=FAINT)
        self.e_name.pack(side="left", fill="x", expand=True)
        self.stamp = tk.Label(head, text="", bg=PAPER, fg=FAINT, font=app.f_meta,
                              justify="right")
        self.stamp.pack(side="right")
        tk.Frame(c, bg=STAMP, height=2).pack(fill="x", pady=(6, 0), **pad)

        self.map = BodyMap(app, c, pad)

        row = tk.Frame(c, bg=PAPER)
        row.pack(fill="x", **pad)
        self.v_type = tk.StringVar()
        self.type_of = {tr(HEALTH_TYPE_LABEL[t]): t for t in HEALTH_TYPES}
        self.e_type = self.combo(row, tr("TYPE"), self.v_type, list(self.type_of), 22, True)
        self.e_type.bind("<<ComboboxSelected>>", self.type_changed)
        self.v_system = tk.StringVar()
        self.e_system = self.combo(row, tr("SYSTEM"), self.v_system,
                                   [system_label(s) for s in SYSTEMS], 20)
        self.e_system.bind("<<ComboboxSelected>>", app.mark_dirty)

        # one block of fields per type; only the record's type is shown, but every
        # block keeps what was loaded, so changing the type loses nothing
        self.typebox = tk.Frame(c, bg=PAPER)
        self.typebox.pack(fill="x")
        self.blocks = {t: tk.Frame(self.typebox, bg=PAPER) for t in HEALTH_TYPES}

        b = self.blocks["measure"]
        r1 = tk.Frame(b, bg=PAPER)
        r1.pack(fill="x", **pad)
        self.e_unit = self.small(r1, tr("UNIT"))
        self.e_lo = self.small(r1, tr("REF. MIN."))
        self.e_hi = self.small(r1, tr("REF. MAX."))
        lbl = app.label(b, tr("READINGS  (one per line:  2026-09-01 [10:30]  value  note)"), pad)
        self.t_read = app.textfield_bare(b, 3, pad)
        app.readable(lbl, self.t_read, tr("READINGS"))
        self.summary = tk.Label(b, text="", bg=PAPER, fg=SOFT, font=app.f_meta, anchor="w")
        self.summary.pack(fill="x", pady=(2, 0), **pad)
        self.trend = tk.Canvas(b, height=96, bg=PAPER, highlightthickness=0, bd=0)
        self.trend.pack(fill="x", pady=(6, 0), **pad)
        self.trend.bind("<Configure>", lambda e: self.draw_trend())
        self.e_new = self.add_row(b, tr("+ today's reading"), self.add_reading, pad)

        b = self.blocks["medication"]
        r1 = tk.Frame(b, bg=PAPER)
        r1.pack(fill="x", **pad)
        self.e_dose = self.small(r1, tr("DOSE"), 14)
        self.e_freq = self.small(r1, tr("FREQUENCY"), 14)
        self.e_start = self.small(r1, tr("SINCE"), 11)
        self.e_end = self.small(r1, tr("UNTIL"), 11)
        self.e_purpose = app.field(b, tr("FOR"), app.f_body, pad)
        self.e_prescriber = app.field(b, tr("PRESCRIBED BY  (a person's p_…, or a name)"),
                                      app.f_meta, pad)
        self.med_state = tk.Label(b, text="", bg=PAPER, fg=OXIDE, font=app.f_meta, anchor="w")
        self.med_state.pack(fill="x", pady=(4, 0), **pad)

        b = self.blocks["activity"]
        self.e_target = app.field(b, tr("AIM  (e.g. 3 times a week)"), app.f_meta, pad)
        lbl = app.label(b, tr("SESSIONS  (one per line:  2026-10-15  60 min  note)"), pad)
        self.t_sessions = app.textfield_bare(b, 3, pad)
        app.readable(lbl, self.t_sessions, tr("SESSIONS"))
        self.sess_summary = tk.Label(b, text="", bg=PAPER, fg=SOFT, font=app.f_meta, anchor="w")
        self.sess_summary.pack(fill="x", pady=(2, 0), **pad)
        self.e_session = self.add_row(b, tr("+ today's session"), self.add_session, pad)

        b = self.blocks["event"]
        r1 = tk.Frame(b, bg=PAPER)
        r1.pack(fill="x", **pad)
        self.v_kind = tk.StringVar()
        self.kind_of = {tr(k): k for k in EVENT_KINDS}
        self.e_kind = self.combo(r1, tr("KIND"), self.v_kind, list(self.kind_of), 16, True)
        self.e_kind.bind("<<ComboboxSelected>>", app.mark_dirty)
        self.e_date = self.small(r1, tr("DATE"), 12)
        self.e_doctor = app.field(b, tr("WITH  (a person's p_…, or a name)"), app.f_meta, pad)
        self.e_place = app.field(b, tr("PLACE"), app.f_meta, pad)
        self.ctype = "measure"

        self.e_source = app.source_field(c, pad)
        self.t_geo = app.geo_field(c, pad)
        self.e_tags = app.field(c, tr("TAGS"), app.f_meta, pad)
        self.t_notes = app.textfield(c, tr("NOTES"), 2, app.f_body, pad, pages=True)

        b = tk.Frame(c, bg=PAPER)
        b.pack(fill="x")
        app.label(b, tr("LINKS  (rel  target  — reason)"), pad)
        self.t_edges = tk.Text(b, height=2, width=1, font=app.f_meta, bg=PAPER, fg=INK,
                               insertbackground=INK, relief="flat", wrap="word",
                               highlightthickness=0, padx=0, spacing1=1, spacing3=3,
                               undo=True, autoseparators=True, maxundo=-1)
        app.block_caret(self.t_edges, app.f_meta)
        app.bind_undo(self.t_edges, text=True)
        self.t_edges.pack(fill="x", **pad)
        app.autogrow(self.t_edges, minrows=2)
        tk.Frame(b, bg=RULE, height=1).pack(fill="x", pady=(4, 0), **pad)
        app.label(c, tr("RESOLVED LINKS  (double-click opens)"), pad)
        self.outbox = app.listbox(c, pad)
        self.outbox.bind("<Double-Button-1>", lambda e: app.jump(self.outbox, self.out_ids))
        app.label(c, tr("CITED BY  (double-click opens)"), pad)
        self.inbox = app.listbox(c, pad)
        self.inbox.bind("<Double-Button-1>", lambda e: app.jump(self.inbox, self.in_ids))
        self.t_links = app.textfield(c, tr("URLS"), 2, app.f_meta, pad)
        tk.Frame(c, bg=PAPER, height=12).pack(fill="x")

        self.entries = [self.e_name, self.e_unit, self.e_lo, self.e_hi, self.e_source,
                        self.e_tags, self.e_new, self.e_dose, self.e_freq, self.e_start,
                        self.e_end, self.e_purpose, self.e_prescriber, self.e_target,
                        self.e_session, self.e_date, self.e_doctor, self.e_place]
        self.texts = [self.t_notes, self.t_read, self.t_edges, self.t_links, self.t_sessions,
                      self.t_geo]
        app.bind_undo(self.e_name)
        for w in self.entries + self.texts:
            for ev in ("<KeyRelease>", "<<Paste>>", "<<Cut>>"):
                w.bind(ev, app.mark_dirty, add="+")
        self.t_read.bind("<KeyRelease>", lambda e: self.refresh_summary(), add="+")
        for w in (self.e_lo, self.e_hi):
            w.bind("<KeyRelease>", lambda e: self.refresh_summary(), add="+")
        self.t_sessions.bind("<KeyRelease>", lambda e: self.refresh_sessions(), add="+")
        self.e_end.bind("<KeyRelease>", lambda e: self.refresh_med(), add="+")
        self.e_start.bind("<KeyRelease>", lambda e: self.refresh_med(), add="+")
        self.apply_type()

    # ---- pieces of the card
    def small(self, parent, title, width=8):
        col = tk.Frame(parent, bg=PAPER)
        col.pack(side="left", fill="x", expand=True, padx=(0, 10))
        tk.Label(col, text=title, bg=PAPER, fg=FAINT, font=self.app.f_label,
                 anchor="w").pack(fill="x", pady=(8, 2))
        ent = tk.Entry(col, width=width, font=self.app.f_meta, bg=PAPER, fg=INK,
                       insertbackground=INK, relief="flat", highlightthickness=0,
                       disabledbackground=PAPER, disabledforeground=FAINT)
        ent.pack(fill="x")
        tk.Frame(col, bg=RULE, height=1).pack(fill="x", pady=(4, 0))
        self.app.bind_undo(ent)
        return ent

    def combo(self, parent, title, var, values, width, readonly=False):
        col = tk.Frame(parent, bg=PAPER)
        col.pack(side="left", padx=(0, 14))
        tk.Label(col, text=title, bg=PAPER, fg=FAINT, font=self.app.f_label,
                 anchor="w").pack(fill="x", pady=(8, 2))
        box = ttk.Combobox(col, textvariable=var, values=values, width=width,
                           font=self.app.f_meta, state="readonly" if readonly else "normal")
        box.pack(anchor="w")
        box.readonly = readonly
        return box

    def add_row(self, parent, button, command, pad):
        row = tk.Frame(parent, bg=PAPER)
        row.pack(fill="x", pady=(3, 10), **pad)
        e = tk.Entry(row, width=1, font=self.app.f_body, bg=PAPER, fg=INK, relief="flat",
                     highlightthickness=1, highlightbackground=RULE, highlightcolor=STAMP,
                     disabledbackground=PAPER, disabledforeground=FAINT)
        e.pack(side="left", fill="x", expand=True, ipady=2)
        e.bind("<Return>", lambda ev: command())
        ttk.Button(row, text=button, command=command).pack(side="left", padx=(8, 0))
        return e

    def apply_type(self):
        for f in self.blocks.values():
            f.pack_forget()
        self.blocks[self.ctype].pack(fill="x")

    def type_changed(self, _e=None):
        self.ctype = self.type_of.get(self.v_type.get(), "measure")
        self.apply_type()
        self.app.mark_dirty()
        self.app.root.after_idle(self.app.refit_card)

    def refresh_med(self):
        end, start = self.e_end.get().strip(), self.e_start.get().strip()
        if end and end < TODAY():
            text = tr("ended on {date}", date=end)
        else:
            text = tr("in use") + (" · " + tr("since {date}", date=start) if start else "")
        self.med_state.configure(text=text)

    def refresh_sessions(self):
        ss = parse_log(self.t_sessions.get("1.0", "end-1c"))
        if not ss:
            self.sess_summary.configure(text=tr("no sessions"))
            return
        month = (date.today() - timedelta(days=30)).isoformat()
        recent = sum(1 for x in ss if x["date"] >= month)
        self.sess_summary.configure(text=tr("{n} sessions · {m} in the last 30 days · last {date}",
                                            n=len(ss), m=recent,
                                            date=max(x["date"] for x in ss)))

    def add_session(self):
        text = self.e_session.get().strip()
        if not self.app.current() or not text:
            return
        existing = self.t_sessions.get("1.0", "end-1c").rstrip()
        line = text if LOG_RE.match(text) and LOG_RE.match(text).group(2) else f"{TODAY()}   {text}"
        self.t_sessions.delete("1.0", "end")
        self.t_sessions.insert("1.0", (existing + "\n" + line) if existing else line)
        self.e_session.delete(0, "end")
        self.app.mark_dirty()
        self.app.refit_card()
        self.app.save()

    def enable(self, on):
        state = "normal" if on else "disabled"
        for w in self.entries + self.texts:
            w.configure(state=state)
        self.e_system.configure(state="normal" if on else "disabled")
        for box in (self.e_type, self.e_kind):
            box.configure(state=("readonly" if on else "disabled"))

    def clear(self):
        for w in self.entries:
            w.delete(0, "end")
        for t in self.texts:
            t.delete("1.0", "end")
        self.v_system.set("")
        self.v_type.set("")
        self.v_kind.set("")
        self.med_state.configure(text="")
        self.sess_summary.configure(text="")
        self.outbox.delete(0, "end")
        self.inbox.delete(0, "end")
        self.summary.configure(text="")
        self.map.set_current(None)
        self.app.update_geo_hint(self.t_geo)
        self.stamp.configure(text="")
        self.msg.configure(text="")

    def open(self, m):
        self.enable(True)
        self.e_name.delete(0, "end")
        self.e_name.insert(0, m.get("name", ""))
        self.v_system.set(system_label(m.get("system", "")))
        self.ctype = htype(m)
        self.v_type.set(tr(HEALTH_TYPE_LABEL[self.ctype]))
        self.v_kind.set(tr(m["etype"]) if m.get("etype") else "")
        for w, k in ((self.e_unit, "unit"), (self.e_lo, "ref_low"), (self.e_hi, "ref_high"),
                     (self.e_source, "source"), (self.e_dose, "dose"), (self.e_freq, "frequency"),
                     (self.e_start, "start"), (self.e_end, "end"), (self.e_purpose, "purpose"),
                     (self.e_prescriber, "prescriber"), (self.e_target, "target"),
                     (self.e_date, "date"), (self.e_doctor, "doctor"), (self.e_place, "place")):
            w.delete(0, "end")
            w.insert(0, str(m.get(k, "") or ""))
        self.app.update_source_hint(self.e_source)
        self.e_tags.delete(0, "end")
        self.e_tags.insert(0, ", ".join(m.get("tags", [])))
        self.t_notes.delete("1.0", "end")
        self.t_notes.insert("1.0", m.get("notes", ""))
        self.t_read.delete("1.0", "end")
        self.t_read.insert("1.0", format_readings(m.get("readings", [])))
        self.t_sessions.delete("1.0", "end")
        self.t_sessions.insert("1.0", format_log(m.get("sessions", [])))
        self.app.geo_put(self.t_geo, m.get("geo", ""))
        self.apply_type()
        self.refresh_med()
        self.refresh_sessions()
        self.t_links.delete("1.0", "end")
        self.t_links.insert("1.0", "\n".join(m.get("links", [])))
        self.t_edges.delete("1.0", "end")
        text = format_edges(edges_from(self.app.data, m["id"]))
        if m.get("edge_drafts"):
            text = "\n".join(filter(None, [text] + m["edge_drafts"]))
        self.t_edges.insert("1.0", text)
        rid = m["id"] if not m["id"].startswith("__") else tr("draft")
        self.stamp.configure(text=f"{rid}\n{m.get('updated', '')}")
        self.msg.configure(text="")
        self.refresh_summary()
        self.refresh_neighbours(m["id"])
        self.map.set_current(m.get("system") or "outro")

    def draw_trend(self):
        """The readings' curve, as a line, with the reference range hatched.
        It is measured from what is typed, so it follows the editing."""
        cv = self.trend
        if not cv.winfo_exists():
            return
        cv.delete("all")
        W, H = cv.winfo_width(), int(cv.cget("height"))
        if W < 60:
            return
        m = {"ref_low": self.e_lo.get().strip(), "ref_high": self.e_hi.get().strip()}
        rs = [r for r in parse_readings(self.t_read.get("1.0", "end-1c"))
              if reading_number(r["value"]) is not None]
        if not rs:
            cv.create_text(0, H // 2, text=tr("(no numeric readings)"), anchor="w",
                           fill=FAINT, font=self.app.f_label)
            return
        vals = [reading_number(r["value"]) for r in rs]
        lo = reading_number(m["ref_low"]) if m["ref_low"] else None
        hi = reading_number(m["ref_high"]) if m["ref_high"] else None
        vmin = min(vals + [v for v in (lo, hi) if v is not None])
        vmax = max(vals + [v for v in (lo, hi) if v is not None])
        if vmin == vmax:
            vmin, vmax = vmin - 1, vmax + 1
        padL, padR, padT, padB = 4, 40, 10, 16

        def X(i):
            return padL + (i / max(1, len(rs) - 1)) * (W - padL - padR)

        def Y(v):
            return padT + (1 - (v - vmin) / (vmax - vmin)) * (H - padT - padB)

        if lo is not None or hi is not None:
            y0 = Y(hi) if hi is not None else padT
            y1 = Y(lo) if lo is not None else H - padB
            cv.create_rectangle(padL, y0, W - padR, y1, outline="", fill=RULE,
                                stipple="gray25")
        cv.create_line(padL, H - padB, W - padR, H - padB, fill=RULE)
        pts = []
        for i, v in enumerate(vals):
            pts.extend((X(i), Y(v)))
        if len(rs) > 1:
            cv.create_line(*pts, fill=INK, width=1.6, joinstyle="round", capstyle="round")
        for i, (r, v) in enumerate(zip(rs, vals)):
            out = out_of_range(m, r)
            cv.create_oval(X(i) - 3, Y(v) - 3, X(i) + 3, Y(v) + 3, outline=INK,
                           fill=INK if out else PAPER, width=1.4)
        cv.create_text(X(len(rs) - 1) + 8, Y(vals[-1]), text=rs[-1]["value"], anchor="w",
                       fill=INK, font=self.app.f_label)
        cv.create_text(padL, H - 2, text=rs[0]["date"][:10], anchor="sw", fill=FAINT,
                       font=self.app.f_label)
        if len(rs) > 1:
            cv.create_text(W - padR, H - 2, text=rs[-1]["date"][:10], anchor="se",
                           fill=FAINT, font=self.app.f_label)
        if hi is not None:
            cv.create_text(W - padR + 8, Y(hi), text=f"{hi:g}", anchor="w", fill=FAINT,
                           font=self.app.f_label)
        if lo is not None:
            cv.create_text(W - padR + 8, Y(lo), text=f"{lo:g}", anchor="w", fill=FAINT,
                           font=self.app.f_label)

    def refresh_summary(self):
        self.draw_trend()
        m = {"ref_low": self.e_lo.get().strip(), "ref_high": self.e_hi.get().strip()}
        rs = parse_readings(self.t_read.get("1.0", "end-1c"))
        if not rs:
            self.summary.configure(text=tr("no readings"))
            return
        nums = [reading_number(r["value"]) for r in rs]
        nums = [n for n in nums if n is not None]
        out = sum(1 for r in rs if out_of_range(m, r))
        txt = tr("{n} readings · latest {date} = {value}", n=len(rs),
                 date=rs[-1]["date"], value=rs[-1]["value"])
        if nums:
            txt += tr(" · min {lo} · max {hi} · mean {mean}", lo=f"{min(nums):g}",
                      hi=f"{max(nums):g}", mean=f"{sum(nums)/len(nums):.2f}")
        if out:
            txt += tr(" · {n} out of range", n=out)
        self.summary.configure(text=txt)

    def refresh_neighbours(self, mid):
        app = self.app
        data, idx = app.data, by_id(app.data)
        self.outbox.delete(0, "end")
        self.out_ids = []
        for a in edges_from(data, mid):
            target = idx.get(a["to"])
            self.outbox.insert("end", f"{link_rel_text(a):18} "
                                      f"{label_any(target, data) if target else a['to']}")
            self.out_ids.append(a["to"])
        self.inbox.delete(0, "end")
        self.in_ids = []
        for a in edges_to(data, mid):
            src = idx.get(a["from"])
            self.inbox.insert("end", f"{label_any(src, data):30} {link_rel_text(a)}")
            self.in_ids.append(a["from"])
        for lb in (self.outbox, self.inbox):
            lb.configure(height=max(2, min(8, lb.size())))

    def gather(self, m):
        out = {k: v for k, v in m.items() if not k.startswith("_")}
        out.update({
            "name": self.e_name.get().strip(),
            "system": system_key(self.v_system.get()),
            "unit": self.e_unit.get().strip(),
            "ref_low": self.e_lo.get().strip().replace(",", "."),
            "ref_high": self.e_hi.get().strip().replace(",", "."),
            "source": self.e_source.get().strip(),
            "geo": self.t_geo.get("1.0", "end-1c").strip(),
            "tags": [t.strip() for t in self.e_tags.get().split(",") if t.strip()],
            "notes": self.t_notes.get("1.0", "end-1c").strip(),
            "readings": parse_readings(self.t_read.get("1.0", "end-1c")),
            "links": [l.strip() for l in self.t_links.get("1.0", "end-1c").splitlines()
                      if l.strip()],
            "ctype": self.ctype,
            "dose": self.e_dose.get().strip(),
            "frequency": self.e_freq.get().strip(),
            "start": self.e_start.get().strip(),
            "end": self.e_end.get().strip(),
            "purpose": self.e_purpose.get().strip(),
            "prescriber": self.e_prescriber.get().strip(),
            "target": self.e_target.get().strip(),
            "sessions": parse_log(self.t_sessions.get("1.0", "end-1c")),
            "etype": self.kind_of.get(self.v_kind.get(), m.get("etype", "")),
            "date": self.e_date.get().strip(),
            "doctor": self.e_doctor.get().strip(),
            "place": self.e_place.get().strip(),
        })
        return out

    def edges_text(self):
        return self.t_edges.get("1.0", "end-1c")

    def add_reading(self):
        text = self.e_new.get().strip()
        if not self.app.current() or not text:
            return
        existing = self.t_read.get("1.0", "end-1c").rstrip()
        line = text if READING_RE.match(text) else f"{TODAY()}   {text}"
        self.t_read.delete("1.0", "end")
        self.t_read.insert("1.0", (existing + "\n" + line) if existing else line)
        self.e_new.delete(0, "end")
        self.app.mark_dirty()
        self.app.refit_card()
        self.app.save()


