class MarkdownKeys:
    """Markdown editing in the long texts: a draft's text, a record's NOTES and
    both in reading mode. The text stays plain markdown; the keys only type it,
    and the look is a light highlight:
      Ctrl+B / Ctrl+I / Ctrl+K   **bold**, *italic*, [[link]] around the
                                 selection (again on a wrapped one: unwraps)
      Ctrl+Backspace / Delete    a whole word
      Enter                      continues a list, a task or a quote; on an
                                 empty item, ends it
      Tab / Shift+Tab            indents a list item (or the selected lines)
      Alt+Up / Alt+Down          moves the line (or the selected lines)
    The window's own Ctrl+B, Ctrl+K... stay as they are everywhere else."""

    ITEM = re.compile(r"^([ \t]*)((?:[-*+]|\d+[.)])[ \t]+(?:\[[ xX/>-]\][ \t]+)?|>[ \t]?)")
    INDENT = "    "
    RULES = (                                   # (tag, pattern, group to colour)
        ("md_code", re.compile(r"^```.*?^```[ \t]*$", re.S | re.M), 0),
        ("md_head", re.compile(r"^#{1,6}[ \t].*$", re.M), 0),
        ("md_quote", re.compile(r"^>.*$", re.M), 0),
        ("md_mark", re.compile(r"^[ \t]*(?:[-*+]|\d+[.)])[ \t]+(?:\[[ xX/>-]\])?", re.M), 0),
        ("md_bold", re.compile(r"\*\*(?=\S)(.+?)(?<=\S)\*\*|__(?=\S)(.+?)(?<=\S)__"), 0),
        ("md_ital", re.compile(r"(?<![*\w])\*(?=[^\s*])(.+?)(?<=[^\s*])\*(?!\*)"
                               r"|(?<![_\w])_(?=\S)(.+?)(?<=\S)_(?![_\w])"), 0),
        ("md_code", re.compile(r"`[^`\n]+`"), 0),
        ("md_link", re.compile(r"\[\[[^\]\n]+\]\]|\[[^\]\n]+\]\([^)\n]+\)"), 0),
        ("md_tag", re.compile(r"(?<![\w#&])#[^\s#.,;:!?()\[\]]+"), 0),
    )

    def __init__(self, app, t):
        self.app, self.t = app, t
        self._job = None
        self.full = True            # repaint everything, or only the lines typed in
        self.lines_typed = set()
        base = tkfont.Font(font=t.cget("font"))
        f = base.actual()
        self.fonts = {
            "md_head": tkfont.Font(family=f["family"], size=f["size"], weight="bold"),
            "md_bold": tkfont.Font(family=f["family"], size=f["size"], weight="bold"),
            "md_ital": tkfont.Font(family=f["family"], size=f["size"], slant="italic"),
            "md_quote": tkfont.Font(family=f["family"], size=f["size"], slant="italic"),
        }
        t.tag_configure("md_head", font=self.fonts["md_head"], foreground=STAMP)
        t.tag_configure("md_bold", font=self.fonts["md_bold"])
        t.tag_configure("md_ital", font=self.fonts["md_ital"])
        t.tag_configure("md_quote", font=self.fonts["md_quote"], foreground=SOFT)
        t.tag_configure("md_code", font=app.f_meta, background=SHELL)
        t.tag_configure("md_link", foreground=STAMP, underline=True)
        t.tag_configure("md_tag", foreground=OXIDE)
        t.tag_configure("md_mark", foreground=SOFT)
        for tag in ("md_link", "md_tag", "md_mark"):
            t.tag_raise(tag)
        if "caret" in t.tag_names():            # the block keeps its colours on a heading
            t.tag_raise("caret")
        t.tag_raise("sel")
        b = t.bind
        b("<Control-b>", lambda e: self.wrap("**"))
        b("<Control-i>", lambda e: self.wrap("*"))
        b("<Control-k>", lambda e: self.wrap("[[", "]]"))
        b("<Control-BackSpace>", lambda e: self.delete_word(-1))
        b("<Control-Delete>", lambda e: self.delete_word(1))
        b("<Return>", self.newline)
        b("<Tab>", lambda e: self.indent(1))
        for seq in ("<Shift-Tab>", "<ISO_Left_Tab>"):
            try:
                b(seq, lambda e: self.indent(-1))
            except tk.TclError:
                pass
        b("<Alt-Up>", lambda e: self.move_lines(-1))
        b("<Alt-Down>", lambda e: self.move_lines(1))
        b("<KeyRelease>", self.typed, add="+")
        for seq in ("<<Paste>>", "<<Cut>>", "<<Undo>>", "<<Redo>>"):
            b(seq, self.later, add="+")

    # ---- keys. Each one is a single step for Ctrl+Z: begin() turns Tk's own
    # separators off, changed() closes the step and turns them back on.
    def begin(self):
        self.t.edit_separator()
        self.t.configure(autoseparators=False)

    def changed(self):
        self.t.edit_separator()
        self.t.configure(autoseparators=True)
        if str(self.t.cget("state")) != "disabled":     # no record open: nothing changed
            self.app.mark_dirty()
            self.later()
        return "break"

    def wrap(self, left, right=None):
        t, right = self.t, right or left
        if str(t.cget("state")) == "disabled":
            return "break"
        self.begin()
        if t.tag_ranges("sel"):
            a, b = t.index("sel.first"), t.index("sel.last")
            inner = t.get(a, b)
            outer_a, outer_b = f"{a} - {len(left)}c", f"{b} + {len(right)}c"
            if inner.startswith(left) and inner.endswith(right) and len(inner) >= len(left + right):
                t.delete(a, b)                                  # unwrap the selection
                inner = inner[len(left):len(inner) - len(right)]
                t.insert(a, inner)
            elif t.get(outer_a, a) == left and t.get(b, outer_b) == right:
                t.delete(b, outer_b)                            # unwrap around it
                t.delete(outer_a, a)
                a = t.index(outer_a)
            else:
                t.delete(a, b)
                t.insert(a, left + inner + right)
                a = t.index(f"{a} + {len(left)}c")
            t.tag_remove("sel", "1.0", "end")
            t.tag_add("sel", a, f"{a} + {len(inner)}c")
            t.mark_set("insert", f"{a} + {len(inner)}c")
        else:
            t.insert("insert", left + right)
            t.mark_set("insert", f"insert - {len(right)}c")
        return self.changed()

    def delete_word(self, way):
        t = self.t
        self.begin()
        if t.tag_ranges("sel"):
            t.delete("sel.first", "sel.last")
            return self.changed()
        if way < 0:
            pos = t.index("insert")
            while t.compare(pos, ">", "1.0") and t.get(f"{pos} - 1c") in " \t":
                pos = t.index(f"{pos} - 1c")
            start = t.index(f"{pos} - 1c wordstart") if t.compare(pos, ">", "1.0") else pos
            t.delete(start, "insert")
        else:
            pos = t.index("insert")
            while t.compare(pos, "<", "end-1c") and t.get(pos) in " \t":
                pos = t.index(f"{pos} + 1c")
            t.delete("insert", t.index(f"{pos} wordend") if t.compare(pos, "<", "end-1c") else pos)
        return self.changed()

    def newline(self, _e=None):
        t = self.t
        if t.tag_ranges("sel"):
            return None
        line = t.get("insert linestart", "insert")
        m = self.ITEM.match(line)
        if not m:
            return None
        lead, mark = m.group(1), m.group(2)
        self.begin()
        if not line[m.end():].strip() and not t.get("insert", "insert lineend").strip():
            t.delete("insert linestart", "insert lineend")      # an empty item ends the list
            return self.changed()
        num = re.match(r"(\d+)([.)])", mark)
        if num:
            mark = f"{int(num.group(1)) + 1}{num.group(2)}" + mark[num.end():]
        mark = re.sub(r"\[[xX/>-]\]", "[ ]", mark)
        t.insert("insert", "\n" + lead + mark)
        t.see("insert")
        return self.changed()

    def lines(self):
        """The first and last line numbers of the selection, or the cursor's."""
        t = self.t
        if t.tag_ranges("sel"):
            a = int(t.index("sel.first").split(".")[0])
            last = t.index("sel.last")
            b = int(last.split(".")[0]) - (1 if last.endswith(".0") and last != t.index("sel.first") else 0)
            return a, max(a, b)
        n = int(t.index("insert").split(".")[0])
        return n, n

    def indent(self, way):
        t = self.t
        a, b = self.lines()
        multi = t.tag_ranges("sel") and a != b
        if not multi and not self.ITEM.match(t.get(f"{a}.0", f"{a}.0 lineend")):
            return None if way > 0 else "break"                # a tab, as usual
        self.begin()
        for n in range(a, b + 1):
            if way > 0:
                t.insert(f"{n}.0", self.INDENT)
            else:
                head = t.get(f"{n}.0", f"{n}.{len(self.INDENT)}")
                cut = 1 if head.startswith("\t") else len(head) - len(head.lstrip(" "))
                if cut:
                    t.delete(f"{n}.0", f"{n}.{cut}")
        return self.changed()

    def move_lines(self, way):
        t = self.t
        a, b = self.lines()
        last = int(t.index("end-1c").split(".")[0])
        if (way < 0 and a == 1) or (way > 0 and b >= last):
            return "break"
        col = t.index("insert").split(".")[1]
        row = int(t.index("insert").split(".")[0])
        had_sel = bool(t.tag_ranges("sel"))
        block = t.get(f"{a}.0", f"{b}.0 lineend")
        self.begin()
        if way < 0:
            above = t.get(f"{a - 1}.0", f"{a - 1}.0 lineend")
            t.delete(f"{a - 1}.0", f"{b}.0 lineend")
            t.insert(f"{a - 1}.0", block + "\n" + above)
        else:
            below = t.get(f"{b + 1}.0", f"{b + 1}.0 lineend")
            t.delete(f"{a}.0", f"{b + 1}.0 lineend")
            t.insert(f"{a}.0", below + "\n" + block)
        a, b, row = a + way, b + way, row + way
        t.mark_set("insert", f"{row}.{col}")
        t.tag_remove("sel", "1.0", "end")
        if had_sel:
            t.tag_add("sel", f"{a}.0", f"{b}.0 lineend")
        t.see("insert")
        return self.changed()

    # ---- highlight. Opening, pasting or undoing paints the whole text; typing
    # repaints only the lines typed in (a long paragraph is laid out again at
    # every repaint, so the whole text would cost tens of ms each pause).
    def typed(self, _e=None):
        n = int(self.t.index("insert").split(".")[0])
        self.lines_typed.update((n - 1, n, n + 1))      # Enter splits a line
        self.later(full=False)

    def later(self, _e=None, full=True):
        self.full = self.full or full
        if self._job:
            try:
                self.t.after_cancel(self._job)
            except tk.TclError:
                pass
        self._job = self.t.after(220, self.paint_and_fit)

    def paint_and_fit(self):
        self._job = None
        if not self.t.winfo_exists():
            return
        last = int(self.t.index("end-1c").split(".")[0])
        if self.full or "```" in self.t.get("1.0", "end-1c"):
            self.paint()
        else:
            for n in sorted(x for x in self.lines_typed if 1 <= x <= last):
                self.paint(n, n)
        self.full, self.lines_typed = False, set()
        for t, fit in self.app.fits:            # a heading or code may change the page
            if t is self.t:
                fit()

    def repaint(self):
        """The whole text, at once: on opening, before the pages are measured."""
        self.paint()
        self.full, self.lines_typed = False, set()

    def paint(self, first=None, last=None):
        """The highlight of the whole text, or of lines first..last."""
        t = self.t
        a, b = (f"{first}.0", f"{last}.0 lineend") if first else ("1.0", "end-1c")
        first = first or 1
        text = t.get(a, b)
        starts, pos = [0], 0
        for line in text.split("\n"):
            pos += len(line) + 1
            starts.append(pos)
        import bisect

        def at(i):
            n = bisect.bisect_right(starts, i) - 1
            return f"{first + n}.{i - starts[n]}"
        for tag, _rx, _g in self.RULES:
            t.tag_remove(tag, a, b)
        code = []
        for tag, rx, g in self.RULES:
            for m in rx.finditer(text):
                a, b = m.span(g)
                if tag != "md_code" and any(x <= a < y for x, y in code):
                    continue                       # nothing is marked inside code
                if tag == "md_code":
                    code.append((a, b))
                t.tag_add(tag, at(a), at(b))


def md_inline(text):
    """Inline markdown to HTML: code, bold, italic, links."""
    import html
    out, parts = [], re.split(r"(`[^`\n]+`)", text)
    for part in parts:
        if part.startswith("`") and part.endswith("`") and len(part) > 1:
            out.append("<code>" + html.escape(part[1:-1]) + "</code>")
            continue
        s_ = html.escape(part)
        s_ = re.sub(r"\*\*(.+?)\*\*|__(.+?)__", lambda m: "<strong>" + (m.group(1) or m.group(2)) + "</strong>", s_)
        s_ = re.sub(r"(?<![*\w])\*(?=[^\s*])(.+?)(?<=[^\s*])\*(?!\*)", r"<em>\1</em>", s_)
        s_ = re.sub(r"\[\[([^\]|]+)\|([^\]]+)\]\]", r'<span class="wl">\2</span>', s_)
        s_ = re.sub(r"\[\[([^\]]+)\]\]", r'<span class="wl">\1</span>', s_)
        s_ = re.sub(r"\[([^\]]+)\]\(([^)\s]+)\)", r'<a href="\2">\1</a>', s_)
        out.append(s_)
    return "".join(out)


def md_to_html(text):
    """A small markdown-to-HTML: headings, paragraphs, lists (nested by indent),
    tasks, quotes, code blocks, rules, inline marks. Enough to read and print."""
    import html
    out, para, stack = [], [], []           # stack: (indent, "ul"|"ol")

    def flush():
        if para:
            out.append("<p>" + md_inline(" ".join(para)) + "</p>")
            para.clear()

    def close_lists(to=-1):
        while stack and stack[-1][0] > to:
            out.append(f"</{stack.pop()[1]}>")

    lines = text.split("\n")
    i = 0
    while i < len(lines):
        line = lines[i]
        if line.strip().startswith("```"):
            flush(); close_lists()
            j = i + 1
            while j < len(lines) and not lines[j].strip().startswith("```"):
                j += 1
            out.append("<pre><code>" + html.escape("\n".join(lines[i + 1:j])) + "</code></pre>")
            i = j + 1
            continue
        m = re.match(r"^(#{1,6})\s+(.*)$", line)
        item = re.match(r"^([ \t]*)([-*+]|\d+[.)])\s+(\[[ xX]\]\s+)?(.*)$", line)
        if m:
            flush(); close_lists()
            n = len(m.group(1))
            out.append(f"<h{n}>{md_inline(m.group(2))}</h{n}>")
        elif re.match(r"^\s*([-*_])(\s*\1){2,}\s*$", line):
            flush(); close_lists()
            out.append("<hr>")
        elif item:
            flush()
            ind = len(item.group(1).expandtabs(4))
            kind = "ol" if item.group(2)[0].isdigit() else "ul"
            if not stack or ind > stack[-1][0]:
                out.append(f"<{kind}>")
                stack.append((ind, kind))
            else:
                close_lists(ind)
                if not stack:
                    out.append(f"<{kind}>")
                    stack.append((ind, kind))
            box = item.group(3)
            mark = ("☑ " if box.strip()[1:2] in "xX" else "☐ ") if box else ""
            out.append("<li>" + mark + md_inline(item.group(4)) + "</li>")
        elif line.startswith(">"):
            flush(); close_lists()
            out.append("<blockquote>" + md_inline(line.lstrip(">").strip()) + "</blockquote>")
        elif not line.strip():
            flush(); close_lists()
        else:
            close_lists()
            para.append(line.strip())
        i += 1
    flush(); close_lists()
    return "\n".join(out)


def note_html(title, body):
    import html
    return ("<!doctype html><html lang=\"pt\"><head><meta charset=\"utf-8\">"
            f"<title>{html.escape(title)}</title><style>"
            "body{max-width:42em;margin:3em auto;padding:0 1.2em;font:17px/1.55 Georgia,serif;"
            "color:#26241f;background:#fbf8f1}h1,h2,h3{line-height:1.2}"
            "code,pre{font:14px Consolas,monospace;background:#eee8da}pre{padding:.8em;overflow:auto}"
            "blockquote{color:#6b6556;border-left:3px solid #d8d0bd;margin:0;padding:0 1em}"
            ".wl{color:#2f5d62;border-bottom:1px dotted}a{color:#2f5d62}"
            "@media print{body{background:#fff;margin:0}}</style></head><body>"
            f"<h1>{html.escape(title)}</h1>\n{md_to_html(body)}</body></html>")


class NoteCard:
    """A draft: a title, tags, the text (markdown, kept in its own file) and
    links like any other record."""

    def __init__(self, app, parent):
        self.app = app
        self.frame = tk.Frame(parent, bg=PAPER)
        self.out_ids, self.in_ids = [], []
        self.opened = None          # the file's time when the note was opened
        self.build()

    def build(self):
        app, shell = self.app, self.frame
        pad = dict(padx=22)
        foot = tk.Frame(shell, bg=PAPER)
        foot.pack(fill="x", side="bottom", pady=12, **pad)
        ttk.Button(foot, text=tr("Save"), command=app.save).pack(side="left")
        ttk.Button(foot, text=tr("Save and new"), style="Quiet.TButton",
                   command=app.save_and_new).pack(side="left", padx=(8, 0))
        self.msg = tk.Label(foot, text="", bg=PAPER, fg=OXIDE, font=app.f_meta)
        self.msg.pack(side="left", padx=14)
        ttk.Button(foot, text=tr("Delete"), style="Quiet.TButton",
                   command=app.delete).pack(side="right")
        ttk.Button(foot, text=tr("open file"), style="Quiet.TButton",
                   command=self.open_file).pack(side="right", padx=(0, 8))
        ttk.Button(foot, text=tr("as HTML"), style="Quiet.TButton",
                   command=self.export_html).pack(side="right", padx=(0, 8))
        tk.Frame(shell, bg=RULE, height=1).pack(fill="x", side="bottom")

        c = app.scroll_area(shell)
        head = tk.Frame(c, bg=PAPER)
        head.pack(fill="x", pady=(11, 0), **pad)
        self.e_name = tk.Entry(head, width=1, font=app.f_name, bg=PAPER, fg=INK,
                               relief="flat", insertbackground=INK, insertwidth=2,
                               highlightthickness=0, disabledbackground=PAPER,
                               disabledforeground=FAINT)
        self.e_name.pack(side="left", fill="x", expand=True)
        self.stamp = tk.Label(head, text="", bg=PAPER, fg=FAINT, font=app.f_meta,
                              justify="right")
        self.stamp.pack(side="right")
        tk.Frame(c, bg=STAMP, height=2).pack(fill="x", pady=(6, 0), **pad)

        self.e_tags = app.field(c, tr("TAGS"), app.f_meta, pad)
        self.e_when = app.field(c, tr("DATE OR PERIOD  (2024-03-11, 1609, 1618/1648 — for the timeline)"),
                                app.f_meta, pad)
        self.t_body = app.textfield(c, tr("TEXT  (markdown)"), 12, app.f_body, pad,
                                    pages=True)
        app.label(c, tr("LINKS  (rel  target  [span]  [@circle]  — reason  # source)"), pad)
        self.t_edges = tk.Text(c, height=2, width=1, font=app.f_meta, bg=PAPER, fg=INK,
                               insertbackground=INK, relief="flat", wrap="word",
                               highlightthickness=0, padx=0, spacing1=1, spacing3=3,
                               undo=True, autoseparators=True, maxundo=-1)
        app.block_caret(self.t_edges, app.f_meta)
        app.bind_undo(self.t_edges, text=True)
        self.t_edges.pack(fill="x", **pad)
        app.autogrow(self.t_edges, minrows=2)
        tk.Frame(c, bg=RULE, height=1).pack(fill="x", pady=(4, 0), **pad)
        app.label(c, tr("RESOLVED LINKS  (double-click opens)"), pad)
        self.outbox = app.listbox(c, pad)
        self.outbox.bind("<Double-Button-1>", lambda e: app.jump(self.outbox, self.out_ids))
        app.label(c, tr("CITED BY  (double-click opens)"), pad)
        self.inbox = app.listbox(c, pad)
        self.inbox.bind("<Double-Button-1>", lambda e: app.jump(self.inbox, self.in_ids))
        self.file_lbl = tk.Label(c, text="", bg=PAPER, fg=FAINT, font=app.f_label,
                                 anchor="w")
        self.file_lbl.pack(fill="x", pady=(8, 14), **pad)

        self.entries = [self.e_name, self.e_tags, self.e_when]
        self.texts = [self.t_body, self.t_edges]
        app.bind_undo(self.e_name)
        for w in self.entries + self.texts:
            for ev in ("<KeyRelease>", "<<Paste>>", "<<Cut>>"):
                w.bind(ev, app.mark_dirty, add="+")

    def enable(self, on):
        state = "normal" if on else "disabled"
        for w in self.entries + self.texts:
            w.configure(state=state)

    def clear(self):
        for w in self.entries:
            w.delete(0, "end")
        for t in self.texts:
            t.delete("1.0", "end")
        for lb in (self.outbox, self.inbox):
            lb.delete(0, "end")
        self.stamp.configure(text="")
        self.file_lbl.configure(text="")
        self.msg.configure(text="")
        self.opened = None

    def open(self, n):
        self.enable(True)
        self.e_name.delete(0, "end")
        self.e_name.insert(0, n.get("name", ""))
        self.e_tags.delete(0, "end")
        self.e_tags.insert(0, ", ".join(n.get("tags", [])))
        body = n["_body"] if n["id"].startswith("__") else note_body(n)
        got = read_note_file(note_path(n)) if n.get("file") else None
        meta = got[1] if got else {}
        when = meta.get("period") or meta.get("date") or ""
        self.e_when.delete(0, "end")
        self.e_when.insert(0, when if isinstance(when, str) else "")
        self.opened = note_mtime(n)
        self.t_body.delete("1.0", "end")
        self.t_body.insert("1.0", body)
        self.t_body.mark_set("insert", "1.0")
        self.t_edges.delete("1.0", "end")
        text = format_edges(edges_from(self.app.data, n["id"]))
        if n.get("edge_drafts"):
            text = "\n".join(filter(None, [text] + n["edge_drafts"]))
        self.t_edges.insert("1.0", text)
        rid = n["id"] if not n["id"].startswith("__") else tr("draft")
        self.stamp.configure(text=f"{rid}\n{n.get('updated') or ''}")
        self.file_lbl.configure(text=n.get("file") or tr("(the file is made on saving)"))
        self.msg.configure(text="")
        self.refresh_neighbours(n["id"])

    def refresh_neighbours(self, nid):
        app = self.app
        data, idx = app.data, by_id(app.data)
        self.outbox.delete(0, "end")
        self.out_ids = []
        for a in edges_from(data, nid):
            target = idx.get(a["to"])
            self.outbox.insert("end", f"{link_rel_text(a):18} "
                                      f"{label_any(target, data) if target else a['to']}")
            self.out_ids.append(a["to"])
        self.inbox.delete(0, "end")
        self.in_ids = []
        for a in edges_to(data, nid):
            src = idx.get(a["from"])
            self.inbox.insert("end", f"{label_any(src, data):30} {link_rel_text(a)}")
            self.in_ids.append(a["from"])
        for lb in (self.outbox, self.inbox):
            lb.configure(height=max(2, min(8, lb.size())))

    def gather(self, n):
        out = {k: v for k, v in n.items() if not k.startswith("_")}
        out["name"] = " ".join(self.e_name.get().split())
        out["tags"] = [t.strip().lstrip("#") for t in self.e_tags.get().split(",")
                       if t.strip().lstrip("#")]
        out["_body"] = self.t_body.get("1.0", "end-1c")
        out["_when"] = " ".join(self.e_when.get().split())
        return out

    def edges_text(self):
        return self.t_edges.get("1.0", "end-1c")

    def export_html(self):
        """The open draft as a web page, beside the program: open it in the
        browser to read, print or save as PDF."""
        rec = self.app.current()
        if not rec:
            return
        self.app.commit_if_dirty()
        rec = self.app.current() or rec
        body = self.t_body.get("1.0", "end-1c")
        name = rec.get("name") or tr("untitled")
        out = BASE / ("_kustos_draft_" + (slug(name)[:60] or "untitled") + ".html")
        out.write_text(note_html(name, body), encoding="utf-8")
        self.app.say(tr("Written {file}", file=out.name))
        try:
            import webbrowser
            webbrowser.open(out.as_uri())
        except Exception:
            pass

    def open_file(self):
        """The draft's .md in the system's program for markdown (Obsidian, if
        it is the one set)."""
        rec = self.app.current()
        path = note_path(rec) if rec else None
        if not path or not path.exists():
            self.app.say(tr("Save the draft first: its file is made on saving."))
            return
        try:
            if hasattr(os, "startfile"):
                os.startfile(path)
            else:
                import subprocess
                subprocess.Popen(["open" if sys.platform == "darwin" else "xdg-open", str(path)])
        except OSError as exc:
            self.app.say(str(exc))


class Reader:
    """Reading mode: one long text field across the whole card, read in pages.

    The text is copied into a widget of its own; typing marks the record dirty,
    and sync() writes it back into the card's field before any save, so saving,
    autosaving and switching records behave exactly as in the card."""

    def __init__(self, app):
        self.app = app
        self.source = None          # the card's Text being read
        self.rid = None             # record it belongs to
        self.starts = None          # display line each page starts on; None = measure again
        self.hits, self.hit_i = [], -1
        f = self.frame = tk.Frame(app.cardbox, bg=PAPER)
        head = tk.Frame(f, bg=PAPER)
        head.pack(fill="x", padx=22, pady=(10, 4))
        # the controls are packed before the title, so a long title is what gets cut
        self.title = tk.Label(head, text="", bg=PAPER, fg=STAMP, font=app.f_label, anchor="w")
        ttk.Button(head, text=tr("close (Esc)"), style="Quiet.TButton",
                   command=self.close).pack(side="right", padx=(8, 0))
        ttk.Button(head, text=tr("find"), style="Quiet.TButton",
                   command=self.find_open).pack(side="right", padx=(8, 0))
        ttk.Button(head, text="›", width=2, style="Quiet.TButton",
                   command=lambda: self.turn(1)).pack(side="right")
        self.page = tk.Label(head, text="", bg=PAPER, fg=SOFT, font=app.f_meta)
        self.page.pack(side="right", padx=6)
        ttk.Button(head, text="‹", width=2, style="Quiet.TButton",
                   command=lambda: self.turn(-1)).pack(side="right")
        self.title.pack(side="left", fill="x", expand=True)
        self.findrow = tk.Frame(f, bg=PAPER)
        self.q = tk.StringVar()
        self.e_find = tk.Entry(self.findrow, textvariable=self.q, font=app.f_meta, bg=PAPER,
                               fg=INK, insertbackground=INK, relief="flat", highlightthickness=1,
                               highlightbackground=RULE, highlightcolor=STAMP)
        self.e_find.pack(side="left", fill="x", expand=True, ipady=2)
        self.found = tk.Label(self.findrow, text="", bg=PAPER, fg=OXIDE, font=app.f_meta)
        self.found.pack(side="left", padx=10)
        self.rule = tk.Frame(f, bg=STAMP, height=2)
        self.rule.pack(fill="x", padx=22)
        t = self.t = tk.Text(f, wrap="word", font=app.f_body, bg=PAPER, fg=INK, relief="flat",
                             insertbackground=INK, highlightthickness=0, padx=22, pady=12,
                             spacing1=2, spacing3=6, undo=True, autoseparators=True, maxundo=-1)
        t.pack(fill="both", expand=True)
        t.tag_configure("hit", background=RULE)
        t.tag_configure("cur", background=SELBG, foreground=SELFG)
        app.bind_undo(t, text=True)
        for seq, fn in (("<Prior>", lambda e: self.turn(-1)), ("<Next>", lambda e: self.turn(1)),
                        ("<Escape>", lambda e: self.close()), ("<Control-e>", lambda e: self.close()),
                        ("<Control-f>", lambda e: self.find_open())):
            t.bind(seq, fn)
        notches = WheelNotches()
        t.bind("<MouseWheel>", lambda e: wheel_turn(notches, e, self.turn))
        bind_touchpad(t.bind, lambda e: wheel_turn(notches, e, self.turn))
        t.bind("<Button-4>", lambda e: self.turn(-1))
        t.bind("<Button-5>", lambda e: self.turn(1))
        t.bind("<KeyRelease>", self.typed, add="+")
        t.bind("<Configure>", self.resized)
        self.book = FieldPages(app, t, None, on_show=self.page_shown)
        self.md = MarkdownKeys(app, t)
        t.tag_raise("hit")                      # what was found shows above the marks
        t.tag_raise("cur")
        self._check_job = None
        self.measure = tkfont.Font(font=app.f_body).measure("0") * 92   # ~92 characters a line
        self.q.trace_add("write", lambda *_: self.find_update())
        self.e_find.bind("<Return>", lambda e: self.next_hit(1))
        self.e_find.bind("<Shift-Return>", lambda e: self.next_hit(-1))
        self.e_find.bind("<Escape>", lambda e: self.find_close())
        self.e_find.bind("<Prior>", lambda e: self.turn(-1))
        self.e_find.bind("<Next>", lambda e: self.turn(1))

    @property
    def is_open(self):
        return self.source is not None

    def resized(self, event):
        """Keeps the text column at a readable width: in a wide window the
        margins grow instead of the lines."""
        pad = max(22, (event.width - self.measure) // 2)
        if int(self.t.cget("padx")) != pad:
            self.t.configure(padx=pad)
        if self.starts is not None and (event.width, event.height) == getattr(self, "_size", None):
            return
        self._size = (event.width, event.height)
        self.starts = None                      # F11, a resize: the pages change
        self.app.root.after_idle(self.show_page)

    def open(self, source, title):
        if str(source.cget("state")) == "disabled":
            self.app.say(tr("Open a record first."))
            return
        rec = self.app.current()
        self.source, self.rid = source, self.app.sel
        self.title.configure(text=f"{title}  ·  {one_liner(label_any(rec, self.app.data), 60)}"
                             if rec else title)
        self.book.off()
        self.t.delete("1.0", "end")
        self.t.insert("1.0", source.get("1.0", "end-1c"))
        self.md.repaint()
        self.t.edit_reset()
        card = getattr(source, "pages", None)
        at = source.index(card.starts[card.cur]) if card is not None and card.paged else "1.0"
        self.t.mark_set("insert", at)       # the reader opens on the page the card showed,
        self.open_last = card is not None and card.paged             and card.cur == len(card.starts) - 1     # or on its last, if the card was there
        self.starts = None
        self.find_close()
        self.frame.place(x=0, y=0, relwidth=1, relheight=1)
        self.frame.lift()
        self.t.focus_set()
        self.t.yview_moveto(0)
        self.app.root.after_idle(self.show_page)

    def typed(self, event):
        if event.keysym in ("Prior", "Next", "Escape") or event.keysym.startswith(
                ("Control", "Shift", "Alt")):
            return
        if event.keysym not in ("Up", "Down", "Left", "Right", "Home", "End"):
            self.app.mark_dirty()
        if self._check_job:
            try:
                self.app.root.after_cancel(self._check_job)
            except tk.TclError:
                pass
        self._check_job = self.app.root.after(120, self.check_page)

    def sync(self):
        """Writes the reader's text back into the card's field, if it changed."""
        if not self.is_open:
            return
        text = self.t.get("1.0", "end-1c")
        if text != self.source.get("1.0", "end-1c"):
            self.source.delete("1.0", "end")
            self.source.insert("1.0", text)
            self.app.mark_dirty()

    def close(self, keep=True):
        if not self.is_open:
            return "break"
        if keep:
            self.sync()
        src = self.source
        self.source = self.rid = None
        self.book.off()
        self.frame.place_forget()
        try:
            src.focus_set()
            self.app.refit_card()
        except tk.TclError:
            pass
        return "break"

    # ---- pages: the same as the card's (FieldPages), on the whole card's height:
    # each page starts at an entry or paragraph and holds exactly what fits
    def paginate(self, keep="insert"):
        t = self.t
        if not t.winfo_ismapped() or t.winfo_height() < 40:
            return False                        # not on screen yet: measure on the next call
        self.book.repage(None, keep)
        self.starts = self.book.starts
        return True

    def current_page(self):
        return self.book.cur

    def turn(self, delta):
        if not self.is_open:
            return "break"
        if self.starts is None and not self.paginate():
            return "break"
        self.book.turn(delta)
        return "break"

    def show_page(self):
        if not self.is_open:
            return
        keep = "last" if getattr(self, "open_last", False) else "insert"
        if self.starts is None and not self.paginate(keep):
            self.app.root.after(60, self.show_page)
            return
        self.open_last = False
        self.page_shown()

    def page_shown(self):
        n = max(1, len(self.book.starts))
        self.page.configure(text=tr("page {p} of {n}", p=self.book.cur + 1, n=n))

    def check_page(self):
        """After typing: measure again only if the page on show overflows or
        the cursor has left it."""
        self._check_job = None
        if self.is_open and self.starts is not None and not self.book.holds(None):
            self.paginate("insert")

    # ---- find inside the text
    def find_open(self):
        self.findrow.pack(fill="x", padx=22, pady=(0, 6), before=self.rule)
        self.starts = None                     # the text area just got shorter
        self.e_find.focus_set()
        self.e_find.select_range(0, "end")
        return "break"

    def find_close(self):
        self.t.tag_remove("hit", "1.0", "end")
        self.t.tag_remove("cur", "1.0", "end")
        self.hits, self.hit_i = [], -1
        self.found.configure(text="")
        self.findrow.pack_forget()
        self.starts = None
        if self.is_open:
            self.t.focus_set()
        return "break"

    def find_update(self):
        t = self.t
        t.tag_remove("hit", "1.0", "end")
        t.tag_remove("cur", "1.0", "end")
        self.hits, self.hit_i = [], -1
        q = self.q.get()
        if q:
            idx = "1.0"
            while True:
                pos = t.search(q, idx, nocase=True, stopindex="end",
                               elide=True)          # the other pages too, hidden or not
                if not pos:
                    break
                end = f"{pos}+{len(q)}c"
                t.tag_add("hit", pos, end)
                self.hits.append((pos, end))
                idx = end
        if not q:
            self.found.configure(text="")
        elif not self.hits:
            self.found.configure(text=tr("not found"))
        else:
            self.next_hit(1)

    def next_hit(self, delta):
        if not self.hits:
            return "break"
        self.hit_i = (self.hit_i + delta) % len(self.hits)
        pos, end = self.hits[self.hit_i]
        self.t.tag_remove("cur", "1.0", "end")
        self.t.tag_add("cur", pos, end)
        if self.starts is None:
            self.paginate()
        self.t.mark_set("insert", pos)
        if self.book.paged:
            self.book.show(self.book.page_of(pos))          # the page holding the match
        self.found.configure(text=f"{self.hit_i + 1}/{len(self.hits)}")
        self.show_page()
        return "break"


# ================================================================ window

class App:
    def __init__(self, root, theme, notices):
        self.root = root
        self.theme = theme
        self.restart_theme = None
        self.data = load_json()
        self.sel = None
        self.scope = None          # None | "people" | "entries"
        self.tag = self.viewmode = self.date = None           # people filters
        self.view_circle = None                               # people filter: a circle, or "none"
        self.scope_explicit = False     # scope picked in COLLECTIONS (not implied by a filter)
        self.view_kind = self.view_lang = self.view_domain = None  # verba filters
        self.view_stype = None                                # source filter
        self.view_system = None                               # corpus filter
        self.view_htype = None                                # corpus type filter
        self.source_hints = []
        self.read_titles = {}       # Text widget -> its title, for reading mode
        self.draft = None
        self.dirty = False
        self.loading = False
        self.busy = False
        self.undo_resets = []
        self.carets = []
        self.pendings = []
        self.fits = []
        self.shown = None
        self.mode = "register"     # "register" (number order) | "index" (search)
        self.top = None            # first row of the view; None = the end (the newest)
        self.rows = 0              # how many rows fit in the list right now
        self.page_sig = None       # did the filter change? then the view goes back to the start
        self._fit_job = None
        self.seen = seen_read()    # dust: when each record was last visited (all machines)
        self.seen_new = {}         # this machine's visits not yet written
        self._seen_job = self._dwell_job = None
        self.quick = None          # the wide card's results under the search
        self.quick_items, self.quick_top, self.quick_cur = [], 0, 0
        ui = self.data.get("ui") or {}
        self.max_rows_fixed = bool(ui.get("max_rows"))      # a fixed limit, if the JSON sets one
        self.max_rows = int(ui.get("max_rows") or 10)
        self.long_text = ui.get("long_text") or "pages"     # "pages" | "continuous"
        self.long_var = tk.StringVar(value=self.long_text)
        self.locked_panes = bool(ui.get("panes_locked"))
        self.locked_var = tk.BooleanVar(value=self.locked_panes)

        serif = self.pick(["Times New Roman", "Liberation Serif",
                           "DejaVu Serif", "Georgia"], "Times")
        mono = self.pick(["Consolas", "Cascadia Mono", "Lucida Console",
                          "DejaVu Sans Mono", "Courier New"], "Courier")
        wanted = ui.get("font_mono")
        self.font_warning = ""
        if wanted:
            ok, why = self.usable_mono(wanted)
            if ok:
                mono = wanted
            else:
                self.font_warning = tr('Typeface "{name}" {why}; using {mono}.',
                                       name=wanted, why=why, mono=mono)
        body = mono if PAL["mono_only"] else serif
        self.f_name = (body, 15 if PAL["mono_only"] else 17)
        self.f_body = (body, 11)
        self.f_row = (body, 11)
        self.f_meta = (mono, 9)
        self.f_label = (mono, 8)

        root.title("Index")
        sw, sh = root.winfo_screenwidth(), root.winfo_screenheight()
        w, h = min(1180, sw - 80), min(740, sh - 120)
        root.geometry(f"{w}x{h}+{max(0, (sw - w) // 2)}+{max(0, (sh - h) // 3)}")
        root.minsize(760, 470)
        root.configure(bg=SHELL)

        st = ttk.Style(root)
        st.theme_use("clam")
        st.configure("TFrame", background=SHELL)
        self.row_h = 24
        st.configure("Treeview", background=SHELL, fieldbackground=SHELL,
                     foreground=INK, borderwidth=0, rowheight=self.row_h, font=self.f_row)
        st.map("Treeview", background=[("selected", SELBG)],
               foreground=[("selected", SELFG)])
        st.configure("TScrollbar", background=RULE, troughcolor=SHELL,
                     bordercolor=SHELL, arrowcolor=SOFT, borderwidth=0,
                     gripcount=0, relief="flat", arrowsize=11)
        st.map("TScrollbar", background=[("active", SOFT)])
        st.configure("Sash", gripcount=0, sashthickness=4, background=RULE,
                     bordercolor=RULE, lightcolor=RULE, darkcolor=RULE)
        st.configure("Tag.Treeview", font=self.f_meta, rowheight=19)
        st.configure("TButton", background=PAPER, foreground=STAMP,
                     font=self.f_meta, borderwidth=1, focuscolor=STAMP,
                     padding=(9, 3), bordercolor=RULE, lightcolor=RULE,
                     darkcolor=RULE, relief="solid")
        st.map("TButton", background=[("active", SELBG)])
        st.configure("Quiet.TButton", foreground=SOFT)

        self.build_bar()
        self.build_body()
        self.build_status()
        self.build_menu()
        self.bind_keys()
        self.reload()
        paint_frame(root)
        self.root.after(300, self.take_in_waiting)
        if notices:
            self.root.after(500, lambda: self.say(" · ".join(notices)))
        elif self.font_warning:
            self.root.after(600, lambda: self.say(self.font_warning))

    def pick(self, names, fallback):
        have = set(tkfont.families(self.root))
        for n in names:
            if n in have:
                return n
        return fallback

    # ------------------------------------------------------------ chrome
    def build_bar(self):
        bar = tk.Frame(self.root, bg=PAPER, highlightthickness=0)
        bar.pack(fill="x")
        tk.Frame(self.root, bg=RULE, height=1).pack(fill="x")
        tk.Label(bar, text="INDEX", bg=PAPER, fg=STAMP,
                 font=(self.f_meta[0], 10)).pack(side="left", padx=(14, 16), pady=9)
        self.q = tk.StringVar()
        self._q_job = None
        self.q.trace_add("write", lambda *_: self.refresh_list_soon())
        self.entry = tk.Entry(bar, textvariable=self.q, font=(self.f_body[0], 13),
                              bg=PAPER, fg=INK, relief="flat", insertbackground=INK,
                              highlightthickness=1, highlightbackground=RULE,
                              highlightcolor=STAMP)
        self.entry.pack(side="left", fill="x", expand=True, ipady=4)
        self.count = tk.Label(bar, text="", bg=PAPER, fg=OXIDE, font=self.f_meta)
        self.count.pack(side="left", padx=14)
        add = ttk.Button(bar, text=tr("+ new ▾"))
        menu = self.add_menu = self.menu(add)
        for kind in self.NEW_KINDS:
            menu.add_command(label=tr(self.NEW_KINDS[kind][0]),
                             command=lambda k=kind: self.new_window(k))
        menu.add_separator()
        menu.add_command(label=tr("bulk entries"), accelerator="Ctrl+Q", command=self.bulk_add)
        add.configure(command=lambda: menu.tk_popup(add.winfo_rootx(),
                                                    add.winfo_rooty() + add.winfo_height()))
        add.pack(side="right", padx=(4, 12))
        ttk.Button(bar, text=tr("dust off"), style="Quiet.TButton",
                   command=self.dust_off).pack(side="right", padx=(4, 0))

    def build_body(self):
        # opaqueresize off: while the divider is dragged only a thin line moves,
        # and the columns are laid out once, on release, instead of at every pixel
        pw = tk.PanedWindow(self.root, orient="horizontal", opaqueresize=False,
                            sashwidth=4, sashrelief="flat", bd=0, bg=RULE,
                            showhandle=False)
        pw.pack(fill="both", expand=True)

        rail = tk.Frame(pw, bg=SHELL)
        self.rail = ttk.Treeview(rail, columns=("n",), show="tree",
                                 style="Tag.Treeview", selectmode="browse")
        self.rail.column("#0", width=168, stretch=True)
        self.rail.column("n", width=38, anchor="e", stretch=False)
        rsb = ttk.Scrollbar(rail, orient="vertical", command=self.rail.yview)
        self.rail.configure(yscrollcommand=rsb.set)
        rsb.pack(side="right", fill="y")
        self.rail.pack(fill="both", expand=True)
        self.rail.tag_configure("head", foreground=FAINT, font=self.f_label)
        self.rail.tag_configure("on", foreground=OXIDE)
        self.rail.tag_configure("late", foreground=OXIDE)
        self.rail.tag_configure("today", foreground=STAMP)
        self.rail.tag_configure("scope", foreground=STAMP)
        self.rail.tag_configure("zero", foreground=FAINT)
        self.rail.bind("<<TreeviewSelect>>", self.on_rail)
        pw.add(rail, stretch="never", minsize=120)
        self.rail_pane = rail
        self.wide = False

        mid = tk.Frame(pw, bg=SHELL)
        self.chips = tk.Frame(mid, bg=SHELL)       # the filters in force (refresh_chips)
        head = tk.Frame(mid, bg=SHELL)
        head.pack(fill="x")
        self.list_head = head
        self.page_lbl = tk.Label(head, text="", bg=SHELL, fg=STAMP, font=self.f_label,
                                 anchor="w")
        self.page_lbl.pack(side="left", fill="x", expand=True, padx=(8, 0))
        ttk.Button(head, text="›", width=2, style="Quiet.TButton",
                   command=lambda: self.turn(1)).pack(side="right", padx=(2, 4), pady=3)
        ttk.Button(head, text="‹", width=2, style="Quiet.TButton",
                   command=lambda: self.turn(-1)).pack(side="right", pady=3)
        tk.Frame(mid, bg=RULE, height=1).pack(fill="x")
        self.list = ttk.Treeview(mid, columns=("sub", "loc"), show="tree",
                                 selectmode="browse")
        self.list.column("#0", width=215, stretch=True)
        self.list.column("sub", width=165, stretch=True)
        self.list.column("loc", width=96, anchor="e", stretch=False)
        self.list.pack(fill="both", expand=True)
        self.list.tag_configure("sub", foreground=FAINT, font=self.f_meta)
        self.list.tag_configure("cancel", foreground=FAINT, font=self.f_meta)
        self.list.bind("<<TreeviewSelect>>", self.on_pick)
        self.list.bind("<Button-3>", self.row_menu)
        # no scrolling: the list shows what fits, and the rest is the next page
        self.list.bind("<Configure>", self.fit_soon)
        self._list_notches = WheelNotches()
        self.list.bind("<MouseWheel>", lambda e: wheel_turn(self._list_notches, e, self.turn))
        bind_touchpad(self.list.bind, lambda e: wheel_turn(self._list_notches, e, self.turn))
        self.list.bind("<Button-4>", lambda e: self.turn(-1))
        self.list.bind("<Button-5>", lambda e: self.turn(1))
        pw.add(mid, stretch="always", minsize=200)
        self.mid_pane = mid

        self.cardbox = tk.Frame(pw, bg=PAPER)
        self.locus = tk.Label(self.cardbox, text="", bg=PAPER, fg=FAINT,
                              font=self.f_label, anchor="w", padx=22)
        self.locus.pack(fill="x", pady=(8, 0))
        pw.add(self.cardbox, stretch="always", minsize=320)
        self.pw = pw
        self.apply_pane_lock()
        self.deck = tk.Frame(self.cardbox, bg=PAPER)      # the four cards, stacked
        self.deck.pack(fill="both", expand=True)
        self.pc = PersonCard(self, self.deck)
        self.vc = EntryCard(self, self.deck)
        self.sc = SourceCard(self, self.deck)
        self.mc = MetricCard(self, self.deck)
        self.nc = NoteCard(self, self.deck)
        self.cards = {"person": self.pc, "entry": self.vc, "source": self.sc,
                      "metric": self.mc, "note": self.nc}
        self.front = None
        self.reader = Reader(self)
        for card in self.cards.values():
            card.stamp.configure(cursor="hand2")
            card.stamp.bind("<Button-1>", lambda e: self.copy_id())
        self.locus.configure(cursor="hand2")
        self.locus.bind("<Button-1>", lambda e: self.copy_number())
        self.show_card("person")
        for c in self.cards.values():
            c.enable(False)
        self.laid_out = False
        pw.bind("<Configure>", self.first_layout)

    def show_card(self, kind, front=True):
        """Only the card in use is in the deck. Another kind of card is first
        put underneath it and laid out at the card's size, then filled and
        measured there (its fields already have their width) and brought up
        finished, in one paint: showing an empty card and fitting its fields
        afterwards made the card flicker on each click. front=False only
        prepares the card; front_card() then brings it up."""
        self.shown = kind
        frame = self.cards[kind].frame
        if self.front != kind and frame.winfo_manager() != "place":
            frame.place(x=0, y=0, relwidth=1, relheight=1)
            if self.front is not None:
                frame.lower(self.cards[self.front].frame)
            frame.update_idletasks()        # laid out, underneath
        if front:
            self.front_card()

    def front_card(self):
        kind = self.shown or "person"
        if self.front == kind:
            return
        self.cards[kind].frame.lift()
        if self.front is not None:
            self.cards[self.front].frame.place_forget()   # out of the deck: no layout, no Tab
        self.front = kind

    @property
    def card(self):
        return self.cards[self.shown or "person"]

    # ---- pieces shared by the cards
    def listbox(self, parent, pad):
        lb = tk.Listbox(parent, height=2, width=1, font=self.f_meta, bg=PAPER, fg=INK,
                        relief="flat", highlightthickness=0, selectbackground=SELBG,
                        selectforeground=SELFG, activestyle="none")
        lb.pack(fill="x", **pad)
        tk.Frame(parent, bg=RULE, height=1).pack(fill="x", pady=(4, 0), **pad)
        return lb

    def jump(self, lb, ids):
        sel = lb.curselection()
        if sel and sel[0] < len(ids):
            self.goto(ids[sel[0]])

    def textfield_bare(self, parent, rows, pad):
        t = tk.Text(parent, height=rows, width=1, font=self.f_meta, bg=PAPER, fg=INK,
                    relief="flat", wrap="word", insertbackground=INK,
                    highlightthickness=0, padx=0, spacing1=1, spacing3=3,
                    undo=True, autoseparators=True, maxundo=-1)
        self.block_caret(t, self.f_meta)
        self.bind_undo(t, text=True)
        t.pack(fill="x", **pad)
        self.autogrow(t, minrows=rows)
        return t

    def source_field(self, parent, pad):
        """The SOURCE field shared by every card: takes a source's id (s_…) or
        free text. Below it, the resolved name and a button that opens it."""
        self.label(parent, tr("SOURCE  (a source's s_…, or free text)"), pad)
        row = tk.Frame(parent, bg=PAPER)
        row.pack(fill="x", **pad)
        e = tk.Entry(row, width=1, font=self.f_meta, bg=PAPER, fg=INK, relief="flat",
                     insertbackground=INK, highlightthickness=0,
                     disabledbackground=PAPER, disabledforeground=FAINT)
        e.pack(side="left", fill="x", expand=True)
        btn = ttk.Button(row, text=tr("open"), style="Quiet.TButton", width=6,
                         command=lambda: self.goto(e.get().strip()))
        btn.pack(side="right")
        hint = tk.Label(parent, text="", bg=PAPER, fg=SOFT, font=self.f_label, anchor="w")
        hint.pack(fill="x", **pad)
        tk.Frame(parent, bg=RULE, height=1).pack(fill="x", pady=(2, 0), **pad)
        self.bind_undo(e)
        e.bind("<KeyRelease>", lambda ev: self.update_source_hint(e), add="+")
        self.source_hints.append((e, hint, btn))
        return e

    def geo_field(self, parent, pad):
        """The GEO field of every card but the draft's: points, latitude,
        longitude, one per line, or GeoJSON. The line under it says what it
        reads as, or what does not read."""
        t = self.textfield(parent, tr("GEO  (latitude, longitude — a point per line — or GeoJSON)"),
                           1, self.f_meta, pad)
        t.configure(wrap="char")
        t.geo_hint = tk.Label(parent, text="", bg=PAPER, fg=SOFT, font=self.f_label, anchor="w")
        t.geo_hint.pack(fill="x", **pad)
        for ev in ("<KeyRelease>", "<<Paste>>", "<<Cut>>"):
            t.bind(ev, self.mark_dirty, add="+")
            t.bind(ev, lambda e: self.root.after(150, lambda: self.update_geo_hint(t)), add="+")
        return t

    def update_geo_hint(self, t):
        try:
            said = geo_summary(t.get("1.0", "end-1c"))
            t.geo_hint.configure(text=("→ " + said) if said and not said.startswith("(!)") else said,
                                 fg=OXIDE if said.startswith("(!)") else SOFT)
        except tk.TclError:
            pass

    def geo_put(self, t, value):
        """Fills a card's GEO (even while the card is disabled) and its hint."""
        state = t.cget("state")
        t.configure(state="normal")
        t.delete("1.0", "end")
        t.insert("1.0", value or "")
        t.configure(state=state)
        self.update_geo_hint(t)

    def update_source_hint(self, entry):
        for e, hint, btn in self.source_hints:
            if e is not entry:
                continue
            text = entry.get().strip()
            if text.startswith("s_"):
                s, shown = resolve_source(text, self.data)
                hint.configure(text=("→ " + shown) if s else shown,
                               fg=SOFT if s else OXIDE)
                btn.configure(state="normal" if s else "disabled")
            else:
                hint.configure(text=tr("free text (use + source to make it a record)")
                               if text else "", fg=FAINT)
                btn.configure(state="disabled")

    def flash(self, text):
        self.card.msg.configure(text=text)

    def first_layout(self, _event=None):
        if self.laid_out:
            return
        width = self.pw.winfo_width()
        if width < 200:
            return
        self.laid_out = True
        saved = (self.data.get("ui") or {}).get("panes")
        if saved and self.apply_panes(saved, width):
            return
        self.reset_layout()

    def apply_panes(self, saved, width):
        try:
            a, b = float(saved[0]), float(saved[1])
        except (TypeError, ValueError, IndexError):
            return False
        if not (0.05 < a < b < 0.95):
            return False
        try:
            self.set_sash(0, int(width * a))
            self.set_sash(1, int(width * b))
            return True
        except Exception:
            return False

    def set_sash(self, i, x):
        self.pw.sash_place(i, x, 0)

    def get_sash(self, i):
        return self.pw.sash_coord(i)[0]

    def set_long_text(self):
        """View › Long texts: LOG and NOTES read one page per view, or continuous
        (the field grows to one screen and scrolls inside)."""
        self.commit_if_dirty()
        self.long_text = self.long_var.get()
        self.save_prefs({"long_text": None if self.long_text == "pages" else self.long_text})
        self.refit_card()

    def save_prefs(self, patch):
        """Saves window preferences (ui.*) and takes back only those: the records
        loaded in the window keep their search text, drafts and the rest."""
        self.data["ui"] = save_ui(patch).get("ui", {})

    def remember_panes(self):
        if self.wide:
            return
        width = self.pw.winfo_width()
        if width < 200 or self.locked_panes:
            return
        try:
            a = self.get_sash(0) / width
            b = self.get_sash(1) / width
        except Exception:
            return
        if not (0.05 < a < b < 0.95):
            return
        self.save_prefs({"panes": [round(a, 4), round(b, 4)]})

    def toggle_wide(self):
        """F11 / Ctrl+Backslash: the card alone in the window, or back with the rail and list."""
        self.quick_hide()
        if self.wide:
            self.pw.add(self.mid_pane, before=self.cardbox, stretch="always", minsize=200)
            self.pw.add(self.rail_pane, before=self.mid_pane, stretch="never", minsize=120)
            self.wide = False

            def restore():
                saved = (self.data.get("ui") or {}).get("panes")
                if not (saved and self.apply_panes(saved, self.pw.winfo_width())):
                    self.reset_layout()
                self.refresh_list()
            self.root.after_idle(restore)
            self.say(tr("Rail and list back."))
        else:
            self.remember_panes()
            self.pw.forget(self.rail_pane)
            self.pw.forget(self.mid_pane)
            self.wide = True
            self.say(tr("Wide card. F11 brings the rail and the list back."))
        self.root.after_idle(self.refit_card)
        return "break"

    # ---- copying ids, numbers and citations, to paste into SOURCE and LINKS
    def copy_text(self, text):
        self.root.clipboard_clear()
        self.root.clipboard_append(text)
        self.say(tr("Copied: {value}", value=one_liner(text, 90)))

    def copy_id(self, rid=None):
        rid = rid or self.sel
        if not rid or rid.startswith("__"):
            self.say(tr("Save the record first: it gets its id on saving."))
            return "break"
        self.copy_text(rid)
        return "break"

    def copy_number(self, rid=None):
        rec = by_id(self.data).get(rid or self.sel or "")
        if rec and rec.get("reg_n"):
            self.copy_text(f"nº {rec['reg_n']}")
        return "break"

    def row_menu(self, event):
        """Right-click on a list row: copy its id, its number, or (sources) the
        citation, without opening it."""
        iid = self.list.identify_row(event.y)
        if not iid:
            return "break"
        m = self.menu(self.root)
        if iid.startswith("x:"):
            m.add_command(label=tr("Copy register number"),
                          command=lambda: self.copy_text(f"nº {iid[2:]}"))
        else:
            rec = by_id(self.data).get(iid)
            if not rec or iid.startswith("__"):
                return "break"
            m.add_command(label=tr("Copy id") + f"   {iid}", command=lambda: self.copy_id(iid))
            if rec.get("reg_n"):
                m.add_command(label=tr("Copy register number") + f"   nº {rec['reg_n']}",
                              command=lambda: self.copy_number(iid))
            if coll_of(iid) == "sources":
                m.add_command(label=tr("Copy ABNT citation"),
                              command=lambda: self.copy_text(cite(rec, "abnt", self.data)))
            m.add_command(label=tr("Copy as a link line") + f"   about {iid}",
                          command=lambda: self.copy_text(f"about {iid}"))
        try:
            m.tk_popup(event.x_root, event.y_root)
        finally:
            m.grab_release()
        return "break"

    def open_reader(self):
        """Ctrl+E: reading mode for the text field in focus, or the card's notes."""
        if self.reader.is_open:
            return self.reader.close()
        w = self.root.focus_get()
        if w in self.read_titles:
            self.reader.open(w, self.read_titles[w])
        elif self.sel:
            t = getattr(self.card, "t_notes", None)
            if t is not None:
                self.reader.open(t, self.read_titles.get(t, tr("NOTES")))
        return "break"

    def lock_panes(self):
        self.locked_panes = bool(self.locked_var.get())
        self.save_prefs({"panes_locked": self.locked_panes})
        self.apply_pane_lock()
        self.say(tr("Widths locked.") if self.locked_panes else tr("Widths free."))

    def apply_pane_lock(self):
        for seq in ("<Button-1>", "<B1-Motion>", "<ButtonRelease-1>"):
            if self.locked_panes:
                self.pw.bind(seq, lambda e: "break")
            else:
                self.pw.unbind(seq)
        if not self.locked_panes:
            # the class binding moves the sash after this one runs: read it afterwards
            self.pw.bind("<ButtonRelease-1>",
                         lambda e: self.root.after_idle(self.remember_panes), add="+")

    def reset_layout(self):
        width = max(self.pw.winfo_width(), 700)
        rail = max(150, min(210, int(width * 0.17)))
        listw = max(230, int(width * 0.30))
        try:
            self.set_sash(0, rail)
            self.set_sash(1, rail + listw)
        except Exception:
            pass

    def build_status(self):
        tk.Frame(self.root, bg=RULE, height=1).pack(fill="x")
        row = tk.Frame(self.root, bg=PAPER)
        row.pack(fill="x")
        self.status = tk.Label(row, text="", bg=PAPER, fg=SOFT, font=self.f_meta,
                               anchor="w")
        self.status.pack(side="left", padx=12, pady=4)
        tk.Label(row, text=f"{HOST}  ·  {BASE}", bg=PAPER, fg=FAINT,
                 font=self.f_meta).pack(side="right", padx=12)

