    def jump_list(self, i):
        kids = self.list.get_children()
        if kids:
            self.list.selection_set(kids[i])
            self.list.see(kids[i])
        return "break"

    def focus_card(self):
        if self.sel:
            self.card.e_name.focus_set()
        return "break"

    def step_record(self, delta):
        """Ctrl+J / Ctrl+K: next / previous in the list, from anywhere."""
        kids = self.list.get_children()
        if not kids:
            return "break"
        cur = self.list.selection()
        cur = cur[0] if cur else self.sel
        if cur in kids:
            i = kids.index(cur) + delta
        else:
            i = 0 if delta > 0 else len(kids) - 1
        if not 0 <= i < len(kids):
            # past the edge: turn the page
            before = self.top
            self.turn(delta)
            if self.top == before:
                return "break"
            kids = self.list.get_children()
            if not kids:
                return "break"
            i = 0 if delta > 0 else len(kids) - 1
        self.list.selection_set(kids[i])
        self.list.see(kids[i])
        return "break"

    def edge_step(self, delta, _event=None):
        """Down arrow on the last row (or up on the first) turns the page
        instead of doing nothing."""
        kids = self.list.get_children()
        cur = self.list.focus()
        if kids and cur in (kids[-1] if delta > 0 else kids[0],):
            return self.step_record(delta)
        return None

    def turn(self, delta):
        """Turns a page: as many rows as fit in the list."""
        rows = max(1, self.rows or self.rows_fit())
        top = (self.top or 0) + delta * rows
        if top >= len(self.view) or (delta < 0 and (self.top or 0) == 0):
            return "break"            # already on the last (or the first) page
        self.top = max(0, top)
        self.refresh_list()
        kids = self.list.get_children()
        if kids:
            self.list.focus(kids[0] if delta >= 0 else kids[-1])
        return "break"

    def turn_to(self, top):
        """Ctrl+Home / Ctrl+End: start or end of the list."""
        self.top = top
        self.refresh_list()
        return "break"

    def rows_fit(self):
        h = self.list.winfo_height()
        if h < 40:              # not drawn yet
            return 20
        return max(1, (h - 4) // self.row_h)

    def fit_soon(self, _event=None):
        """The window changed size: redraw once it stops changing."""
        if self._fit_job:
            try:
                self.root.after_cancel(self._fit_job)
            except tk.TclError:
                pass
        self._fit_job = self.root.after(90, self.fit)

    def fit(self):
        self._fit_job = None
        if self.rows_fit() != self.rows:
            self.refresh_list()

    def open_book(self):
        """Ctrl+B: the base as a logbook, in a second window, open on the
        current record's page. Read-only; Enter in the logbook brings a record here."""
        self.commit_if_dirty()
        rec = self.current()
        win = tk.Toplevel(self.root)
        win.book = BookView(win, self.data, start_id=(rec or {}).get("id"),
                            on_open=self.open_from_book)
        return "break"

    def open_graph(self):
        """Ctrl+Shift+G: the links as a living graph, in a second window, around
        the current record; it follows the records opened here."""
        self.commit_if_dirty()
        g = getattr(self, "graph", None)
        if g and g.is_open():
            g.root.lift()
            g.follow((self.current() or {}).get("id"))
            return "break"
        win = tk.Toplevel(self.root)
        self.graph = GraphView(win, lambda: self.data, start_id=(self.current() or {}).get("id"),
                               on_open=self.open_from_graph, on_link=self.link_from_graph)
        return "break"

    def write_inverse(self, inverse):
        """The links typed on this card from their other end (cited_by …),
        each saved with the record it starts from; the card then shows them
        under CITED BY. Returns the vault if any was written."""
        if not inverse:
            return None
        data, went, problems = write_inverse_links(inverse)
        self._reshaped = True
        idx = by_id(data or load_json())
        names = ", ".join(one_liner(label_any(idx.get(r), self.data), 30) for r in dict.fromkeys(went))
        bits = [tr("{n} link(s) written from the other end, saved with {names}.",
                   n=len(went), names=names)] if went else []
        if problems:
            bits.append(tr("Not saved: {why}", why="; ".join(problems)))
        self.root.after(50, lambda: self.say(" ".join(bits)))
        return data

    def link_from_graph(self, a, b, rel, why="", source="", when="", circle=""):
        """A link drawn in the graph (Shift+drag), written here: what the card
        holds is saved first, the link is added to the record it comes from
        (write_link, as the web page does), and both windows show it. Returns
        what went wrong, or None."""
        self.commit_if_dirty()
        try:
            data = write_link(a, b, rel, why, source, when, circle=circle)
        except (ValueError, WebConflict) as exc:
            return str(exc)
        except SystemExit as exc:
            return str(exc)
        self.safe_mirror(data)
        self.reload()
        if self.sel in (a, b):
            self.open_record(self.sel)
        g = getattr(self, "graph", None)
        if g and g.is_open():
            g.recentre(g.center, fresh=True)
        self.say(tr("Link saved: {a} {rel} {b}", a=label_any(by_id(self.data).get(a), self.data),
                    rel=rel_label(rel), b=label_any(by_id(self.data).get(b), self.data)))
        return None

    def open_monads(self):
        """Ctrl+Shift+M: what the records share without being linked, in a second
        window, around the current record; it follows the records opened here."""
        self.commit_if_dirty()
        m = getattr(self, "monads", None)
        if m and m.is_open():
            m.root.lift()
            m.follow((self.current() or {}).get("id"))
            return "break"
        win = tk.Toplevel(self.root)
        self.monads = MonadView(win, lambda: self.data, start_id=(self.current() or {}).get("id"),
                                on_open=self.open_from_graph)
        return "break"

    def open_timeline(self):
        """Ctrl+Shift+T: everything dated, on one line of time, in a second
        window; it follows the search and the filters of this one."""
        self.commit_if_dirty()
        tl = getattr(self, "timeline", None)
        if tl and tl.is_open():
            tl.root.lift()
            return "break"
        win = tk.Toplevel(self.root)
        self.timeline = TimelineView(win, lambda: self.data, get_ids=self.timeline_ids,
                                     start_id=(self.current() or {}).get("id"),
                                     on_open=self.open_from_graph)
        return "break"

    def open_practice(self):
        """View › Practice languages: the web app, opened on its practice page."""
        import subprocess
        exe = Path(sys.executable)
        quiet = exe.with_name("pythonw.exe")
        if sys.platform == "win32" and quiet.exists():
            exe = quiet
        try:
            subprocess.Popen([str(exe), str(Path(__file__).resolve()), "web", "--page", "practice"],
                             cwd=str(BASE))
        except OSError as exc:
            self.say(tr("The web version did not start: {why}", why=exc))
            return "break"
        self.say(tr("Practice opens in the browser."))
        return "break"

    def open_peritia(self):
        """View › Skills: the Peritia panel, served by a process of its own, so it
        outlives this window; it stops by itself once its page is closed."""
        import subprocess
        exe = Path(sys.executable)
        quiet = exe.with_name("pythonw.exe")
        if sys.platform == "win32" and quiet.exists():
            exe = quiet
        try:
            subprocess.Popen([str(exe), str(Path(__file__).resolve()), "peritia"], cwd=str(BASE))
        except OSError as exc:
            self.say(tr("Peritia did not start: {why}", why=exc))
            return "break"
        self.say(tr("Peritia opens in the browser."))
        return "break"

    def timeline_ids(self):
        """The ids the search and the filters let through; None for everything."""
        sig = self.filter_sig()
        if not (any(sig[:-1]) or self.view_system is not None):
            return None
        return {r["id"] for r in self.matches()}

    def timeline_soon(self):
        tl = getattr(self, "timeline", None)
        if not tl or not tl.is_open():
            return
        if getattr(self, "_tl_job", None):
            try:
                self.root.after_cancel(self._tl_job)
            except tk.TclError:
                pass
        self._tl_job = self.root.after(300, tl.refresh)

    def open_from_graph(self, rid):
        if rid not in by_id(self.data):
            self.say(tr("{id} does not exist.", id=rid))
            return
        self.goto(rid)
        self.root.lift()
        self.root.focus_force()

    def open_from_book(self, rid):
        if rid not in by_id(self.data):
            self.say(tr("{id} no longer exists (the logbook shows the base as it was "
                        "when opened).", id=rid))
            return
        self.goto(rid)
        self.root.lift()
        self.root.focus_force()

    def to_register(self, n=None):
        """Ctrl+L: leaves the search and the filters and shows the open record
        (or the requested nº) in its place in the sequence."""
        self.commit_if_dirty()
        rec = self.current()
        self.clear_filters()
        self.scope = None
        self.q.set("")
        if self._q_job:          # the empty search is drawn right now instead
            try:
                self.root.after_cancel(self._q_job)
            except tk.TclError:
                pass
            self._q_job = None
        self.refresh_rail()
        self.refresh_list()
        target = n or (rec or {}).get("reg_n")
        if target:
            self.show_number(target)
        self.list.focus_set()
        return "break"

    def show_number(self, n):
        """Moves the view to nº n (mid-page, if possible)."""
        i = self.view_num.get(n)
        if i is None:
            return
        kids = self.list.get_children()
        iid = self.view[i][1].get("id") if self.view[i][0] == "r" else f"x:{n}"
        if iid not in kids:
            self.top = max(0, i - self.rows // 2)
            self.refresh_list()

    def set_scope(self, key):
        self.commit_if_dirty()
        self.clear_filters()
        self.scope = key
        self.scope_explicit = key is not None
        self.refresh_rail()
        self.refresh_list()
        if key == "corpus" and (self.sel is None or self.rec_kind(self.current()) != "metric"):
            self.show_corpus_blank()
        return "break"

    def goto_dialog(self):
        """Ctrl+G: go to a record by number, stamp, id or name."""
        win = self.dialog(tr("Go to"), 520, 130)
        tk.Label(win, text=tr("GO TO  (nº, stamp, id or name)"), bg=PAPER,
                 fg=FAINT, font=self.f_label).pack(anchor="w", padx=18, pady=(14, 2))
        e = tk.Entry(win, font=self.f_body, bg=PAPER, fg=INK, insertbackground=INK,
                     relief="flat", highlightthickness=1, highlightbackground=RULE,
                     highlightcolor=STAMP)
        e.pack(fill="x", padx=18, ipady=3)

        def go(_ev=None):
            key = e.get().strip()
            win.destroy()
            if not key:
                return
            idx = by_id(self.data)
            if key in idx:
                self.goto(key)
                return
            m = re.fullmatch(r"(?i)\s*(?:n[ºo°.]?)?\s*(\d+)\s*", key)
            if m:
                r = find_by_reg(self.data, m.group(1))
                if r and r.get("id") in idx:
                    self.goto(r["id"])
                elif r:
                    self.to_register(r["reg_n"])
                    iid = f"x:{r['reg_n']}"
                    if self.list.exists(iid):
                        self.list.selection_set(iid)
                        self.list.see(iid)
                else:
                    self.say(tr("No record with nº or stamp {key}.", key=m.group(1)))
                return
            low = key.lower()
            hits = [r for r in idx.values() if r.get("name", "").lower() == low]
            if not hits:
                hits = [r for r in idx.values() if low in r.get("name", "").lower()]
            if len(hits) == 1:
                self.goto(hits[0]["id"])
            elif hits:
                self.q.set(key)
                self.say(tr("{n} records with that name; pick one in the list.", n=len(hits)))
            else:
                self.say(tr("Nothing called {key}.", key=key))

        e.bind("<Return>", go)
        win.bind("<Escape>", lambda ev: win.destroy())
        e.focus_set()
        return "break"

    # ------------------------------------------------------------ widgets
    def label(self, parent, text, pad):
        lbl = tk.Label(parent, text=text, bg=PAPER, fg=FAINT, font=self.f_label, anchor="w")
        lbl.pack(fill="x", pady=(6, 2), **pad)
        return lbl

    def readable(self, label, text, title):
        """A double-click on the field's title opens it in reading mode."""
        self.read_titles[text] = title
        label.configure(cursor="hand2")
        label.bind("<Double-Button-1>", lambda e: self.reader.open(text, title))

    def field(self, parent, text, font, pad):
        self.label(parent, text, pad)
        e = tk.Entry(parent, width=1, font=font, bg=PAPER, fg=INK, relief="flat",
                     insertbackground=INK, highlightthickness=0,
                     disabledbackground=PAPER, disabledforeground=FAINT)
        e.pack(fill="x", **pad)
        tk.Frame(parent, bg=RULE, height=1).pack(fill="x", pady=(4, 0), **pad)
        self.bind_undo(e)
        return e

    def textfield(self, parent, text, rows, font, pad, pages=False):
        """A text field under its title. With pages=True it is a long text: read
        in pages (FieldPages), whose buttons sit beside the title, and written in
        markdown (MarkdownKeys)."""
        if pages:
            row = tk.Frame(parent, bg=PAPER)
            row.pack(fill="x", pady=(6, 2), **pad)
            lbl = tk.Label(row, text=text, bg=PAPER, fg=FAINT, font=self.f_label, anchor="w")
            lbl.pack(side="left")
        else:
            lbl = self.label(parent, text, pad)
        box = tk.Frame(parent, bg=PAPER)
        box.pack(fill="x", **pad)
        t = tk.Text(box, height=rows, width=1, font=font, bg=PAPER, fg=INK,
                    relief="flat", wrap="word", insertbackground=INK,
                    highlightthickness=0, padx=0, spacing1=1, spacing3=3,
                    undo=True, autoseparators=True, maxundo=-1)
        self.block_caret(t, font)
        self.bind_undo(t, text=True)
        t.pack(side="left", fill="both", expand=True)
        t.pages = FieldPages(self, t, row) if pages else None
        self.autogrow(t, minrows=rows, pages=t.pages)
        tk.Frame(parent, bg=RULE, height=1).pack(fill="x", pady=(4, 0), **pad)
        self.readable(lbl, t, text.split("  (")[0])
        t.md = MarkdownKeys(self, t) if pages else None
        return t

    def scroll_area(self, parent):
        """The whole card scrolls; the fields inside it do not."""
        canvas = tk.Canvas(parent, bg=PAPER, highlightthickness=0, bd=0)
        bar = ttk.Scrollbar(parent, orient="vertical", command=canvas.yview)
        inner = tk.Frame(canvas, bg=PAPER)
        win = canvas.create_window((0, 0), window=inner, anchor="nw")
        canvas.configure(yscrollcommand=bar.set)
        bar.pack(side="right", fill="y")
        canvas.pack(side="left", fill="both", expand=True)
        pending = {"job": None}

        def apply_region():
            pending["job"] = None
            try:
                if canvas.winfo_exists():
                    canvas.configure(scrollregion=canvas.bbox("all"))
            except tk.TclError:
                pass

        def resized(_e=None):
            if pending["job"]:
                try:
                    canvas.after_cancel(pending["job"])
                except tk.TclError:
                    pass
            pending["job"] = canvas.after(45, apply_region)

        inner.bind("<Configure>", resized)
        seen = {"h": None, "job": None}

        def refit_fields():
            seen["job"] = None
            mine = str(canvas) + "."
            for t, fit in self.fits:
                if str(t).startswith(mine) and t.winfo_exists():
                    fit()

        def canvas_resized(e):
            canvas.itemconfigure(win, width=e.width)
            if e.height != seen["h"]:
                seen["h"] = e.height
                if seen["job"]:
                    try:
                        canvas.after_cancel(seen["job"])
                    except tk.TclError:
                        pass
                seen["job"] = canvas.after(90, refit_fields)

        canvas.bind("<Configure>", canvas_resized)
        scroll = canvas.scroll = {"job": None, "to": 0.0}

        notches = WheelNotches()

        def glide(step):
            """Three units of the wheel (a tenth of the view each) a notch -- a
            touchpad's step, its fraction --, eased. Turning on while it moves
            adds to where it was heading."""
            top, bottom = canvas.yview()
            span = bottom - top
            base = top if scroll["job"] is None else scroll["to"]
            to = scroll["to"] = max(0.0, min(1.0 - span, base + step * 0.3 * span))
            tween(canvas, scroll, SCROLL_MS, lambda k: canvas.yview_moveto(top + (to - top) * k))

        def follow(px):
            """A touchpad moves the card by its own pixels, at once: the card
            follows the fingers, as everywhere else on the system."""
            halt(canvas, scroll)
            box = canvas.bbox("all")
            height = (box[3] - box[1]) if box else 0
            if height <= 0:
                return
            top, bottom = canvas.yview()
            canvas.yview_moveto(max(0.0, min(1.0 - (bottom - top), top + px / height)))

        def move(e, units):
            follow(e.pixels) if getattr(e, "touch", False) else glide(units)

        gesture = {"at": 0.0, "step": 0, "edge": False}

        def wheel(e):
            """The wheel or the touchpad scroll the card, whatever field is under
            the pointer: a long NOTES or LOG filled most of a card and took the
            wheel for its own pages, so the card hardly scrolled. A long field's
            pages turn with a sideways swipe or Shift+wheel over it, or with the
            wheel once the card is at its end -- a gesture that only reaches the
            end does not spill into them."""
            if not canvas.winfo_exists():
                return
            units = wheel_units(e)
            if not units:
                return
            step = 1 if units > 0 else -1
            sideways = bool(getattr(e, "state", 0) & 0x1)   # Shift+wheel; a sideways swipe on Windows
            now = time.monotonic()
            if now - gesture["at"] > WHEEL_GESTURE_S or step != gesture["step"]:
                top, bottom = canvas.yview()            # a new gesture: was the card at its end?
                gesture["edge"] = scroll["job"] is None and (bottom >= 0.999 if step > 0 else top <= 0.001)
                gesture["step"] = step
            gesture["at"] = now
            w = e.widget
            book = getattr(w, "pages", None)
            paged = isinstance(w, tk.Text) and book is not None and book.paged
            if paged and (sideways or gesture["edge"]) and book.can_turn(step):
                if notches(e):                  # a page a notch, however small the steps
                    book.turn(step, focus=False)
                return
            if isinstance(w, tk.Text) and not paged and (sideways or gesture["edge"]):
                first, last_ = w.yview()        # a field that scrolls inside, as a long field pages
                if (last_ < 0.999) if step > 0 else (first > 0.001):
                    px = e.pixels if getattr(e, "touch", False) and e.pixels else units * 40
                    w.yview_scroll(int(round(px)) or step, "pixels")
                    return
            if not sideways:
                move(e, units)

        # Tk sends the wheel to the widget under the pointer, on every system;
        # one handler for the whole window passes it to the card that widget is
        # in (card_wheel). It used to be switched on and off as the pointer came
        # and went, and a click in a field could leave it off.
        canvas.wheel = wheel
        if not getattr(self, "_card_wheel", False):
            self._card_wheel = True
            for seq in ("<MouseWheel>", "<Button-4>", "<Button-5>"):
                self.root.bind_all(seq, self.card_wheel, add="+")
                # a text field scrolled itself before the card heard of it (and,
                # at its end, the card stayed still): in a card, the card decides
                self.root.bind_class("Text", seq, self.text_wheel)
                # a drop-down box changed its value under the wheel -- a source's
                # type, a form's status -- while the card scrolled past it
                self.root.unbind_class("TCombobox", seq)
            # Tk 9's touchpad, the same way (on Tk 8.6 there is no such event)
            if bind_touchpad(lambda seq, fn: self.root.bind_all(seq, fn, add="+"), self.card_wheel):
                bind_touchpad(lambda seq, fn: self.root.bind_class("Text", seq, fn), self.text_touch)
                self.root.unbind_class("TCombobox", "<TouchpadScroll>")
        self.canvases = getattr(self, "canvases", []) + [canvas]
        self.pendings += [(canvas, pending), (canvas, scroll)]
        return inner

    def card_canvas(self, widget):
        """The scrolling canvas of the card a widget is in, or None."""
        path = str(widget)
        for canvas in getattr(self, "canvases", []):
            mine = str(canvas)
            if path == mine or path.startswith(mine + "."):
                return canvas if canvas.winfo_exists() else None
        return None

    def card_wheel(self, e):
        """The wheel or the touchpad over a card -- a field of it included --
        scrolls that card (or turns the field's page), whatever was clicked."""
        canvas = self.card_canvas(e.widget)
        return canvas.wheel(e) if canvas is not None else None

    def text_touch(self, e):
        """A text field's own touchpad (a TouchWheel), as Tk 9 has it -- except
        in a card, where the card decides."""
        if self.card_canvas(e.widget) is not None:
            self.card_wheel(e)
            return "break"
        if e.state & 0x1:
            e.widget.xview_scroll(int(-e.delta) or 0, "pixels")
        elif e.pixels:
            e.widget.yview_scroll(int(e.pixels), "pixels")
        return None

    def text_wheel(self, e):
        """A text field's own wheel, as Tk has it -- except in a card, where
        the card decides (card_wheel) and the field does not move by itself."""
        if self.card_canvas(e.widget) is not None:
            self.card_wheel(e)
            return "break"
        w, num = e.widget, getattr(e, "num", 0)
        if num in (4, 5):
            w.yview_scroll(-50 if num == 4 else 50, "pixels")
        elif sys.platform == "darwin":
            w.yview_scroll(-15 * e.delta, "pixels")
        else:
            d = e.delta
            w.yview_scroll(-d // 3 if d >= 0 else (2 - d) // 3, "pixels")
        return None

    def autogrow(self, t, minrows=2, tail=False, pages=None):
        """As many rows as the text needs, up to one screen of the card: a long
        note reads like a page, and the card's own scroll takes over past it.
        Tk counts the wrapped lines itself, at any length, once its line
        metrics are up to date ("sync"). A field with tail=True (the log, newest
        at the end) opens on its last lines; one with `pages` (a FieldPages) is
        read in pages instead of scrolling inside."""
        last = {"n": None, "w": None, "h": None, "job": None}
        book = pages

        def paged_view():
            if book and self.long_text != "pages":
                book.off()                  # continuous: the whole text, scrolled inside
                return None
            return book

        def rows_needed(limit):
            """The rows the text takes, or just `limit` when it surely takes more:
            counting the wrap of a very long note costs tens of ms."""
            width = t.winfo_width()
            if width <= 1:
                return None
            lines = int(t.index("end-1c").split(".")[0])
            if lines >= limit:
                return lines
            try:
                f = tkfont.Font(font=t.cget("font"))
                narrow = max(1, min(f.measure(c) for c in "il.'"))
                if len(t.get("1.0", "end-1c")) // max(1, width // narrow) >= limit:
                    return limit      # even in its narrowest letters it fills the screen
                t.tk.call(t._w, "sync")
                n = t.count("1.0", "end", "displaylines")
            except tk.TclError:
                return None
            if isinstance(n, tuple):
                n = n[0] if n else 0
            return max(1, n or 0)

        def cap():
            if self.max_rows_fixed:
                return self.max_rows
            w = t.master
            while w is not None and not isinstance(w, tk.Canvas):
                w = w.master
            if w is None or w.winfo_height() <= 1:
                return self.max_rows
            try:
                line = tkfont.Font(font=t.cget("font")).metrics("linespace") + 4
            except tk.TclError:
                return self.max_rows
            # one screen, leaving room to see the field's title and the next one
            return max(self.max_rows, (w.winfo_height() - 72) // line)

        def fit(_e=None, opening=False):
            if not t.winfo_exists():
                return
            if opening and getattr(t, "md", None):
                t.md.repaint()
            pages = paged_view()
            top = cap()
            if pages and pages.paged and not opening and pages.holds(top):
                return
            if pages:
                pages.unhide()          # measure the whole text, not the page on show
            n = rows_needed(top)
            if n is None:
                n = int(t.index("end-1c").split(".")[0])
            n = min(top, max(minrows, n))
            if n != last["n"]:
                last["n"] = n
                t.configure(height=n)
            if pages:
                if n < top:
                    pages.off()
                else:
                    pages.repage(top, ("last" if tail else "first") if opening else "insert")
                return
            if n < top:
                t.yview_moveto(0)
            elif opening:
                t.yview_moveto(1.0 if tail else 0)

        def later(_e=None):
            if last["job"]:
                try:
                    t.after_cancel(last["job"])
                except tk.TclError:
                    pass
            last["job"] = t.after(45, fit)

        def on_configure(e):
            if e.width == last["w"]:
                return
            last["w"] = e.width
            later()

        t.bind("<KeyRelease>", later, add="+")
        t.bind("<Configure>", on_configure, add="+")
        for seq in ("<<Paste>>", "<<Cut>>", "<<Undo>>", "<<Redo>>"):
            t.bind(seq, later, add="+")
        self.fits.append((t, fit))
        self.pendings.append((t, last))
        return fit

    def refit_card(self):
        """Fits the fields and the scroll area of the card in use only; the
        three underneath are fitted when they come up. The card is laid out and
        drawn here, while it may still lie underneath (see show_card): brought
        up already drawn, it changes in one go; drawn only once on top, it
        showed up piece by piece."""
        shown = str(self.card.frame) + "."
        for t, fit in self.fits:
            if str(t).startswith(shown):
                fit(opening=True)
        for canvas in getattr(self, "canvases", []):
            if str(canvas).startswith(shown) and canvas.winfo_exists():
                canvas.update_idletasks()
                canvas.configure(scrollregion=canvas.bbox("all"))
                halt(canvas, canvas.scroll)
                canvas.yview_moveto(0)

    def bind_undo(self, widget, text=False):
        """Ctrl+Z / Ctrl+Y everywhere. Text has its own stack; Entry gets one."""
        if text:
            def undo(_e=None):
                try:
                    widget.edit_undo()
                except tk.TclError:
                    pass
                self.mark_dirty()
                return "break"

            def redo(_e=None):
                try:
                    widget.edit_redo()
                except tk.TclError:
                    pass
                self.mark_dirty()
                return "break"

            self.undo_resets.append(
                lambda w=widget: (w.edit_reset(), w.edit_modified(False)))
        else:
            import time as _time
            hist = {"stack": [""], "pos": 0, "when": 0.0}

            def commit():
                val = widget.get()
                if hist["stack"][hist["pos"]] == val:
                    return
                del hist["stack"][hist["pos"] + 1:]
                hist["stack"].append(val)
                hist["pos"] = len(hist["stack"]) - 1
                if len(hist["stack"]) > 200:
                    hist["stack"].pop(0)
                    hist["pos"] -= 1

            def snapshot(event=None):
                now = _time.monotonic()
                boundary = event is not None and getattr(
                    event, "char", "") in (" ", ",", ".", ";", ":", "-", "/")
                if boundary or now - hist["when"] > 0.7:
                    commit()
                hist["when"] = now

            def restore(val):
                widget.delete(0, "end")
                widget.insert(0, val)
                widget.icursor("end")

            def undo(_e=None):
                commit()
                if hist["pos"] > 0:
                    hist["pos"] -= 1
                    restore(hist["stack"][hist["pos"]])
                    self.mark_dirty()
                return "break"

            def redo(_e=None):
                if hist["pos"] < len(hist["stack"]) - 1:
                    hist["pos"] += 1
                    restore(hist["stack"][hist["pos"]])
                    self.mark_dirty()
                return "break"

            def reset(w=widget):
                hist["stack"] = [w.get()]
                hist["pos"] = 0
                hist["when"] = 0.0

            widget.bind("<KeyRelease>", snapshot, add="+")
            widget.bind("<<Paste>>", lambda e: widget.after(1, commit), add="+")
            self.undo_resets.append(reset)

        for seq in ("<Control-z>", "<Control-Z>"):
            widget.bind(seq, undo)
        for seq in ("<Control-y>", "<Control-Y>", "<Control-Shift-Z>",
                    "<Control-Shift-z>"):
            widget.bind(seq, redo)

    def char_width(self, font):
        try:
            return max(2, tkfont.Font(family=font[0], size=font[1]).measure("M"))
        except Exception:
            return 8

    def stop_carets(self):
        """Cancels every timer before the window is destroyed."""
        for t, state in self.carets + self.pendings:
            try:
                if state.get("job"):
                    t.after_cancel(state["job"])
                    state["job"] = None
            except Exception:
                pass
        self.carets = []

    def block_caret(self, t, font):
        """A block cursor, inverting the character under it. It fades instead of
        blinking, stays lit while in use, and leaves a short afterglow where it
        was. Only the field with the focus has a timer running, and only until
        the caret has been left alone for a while. At the end of a
        line there is no character to invert, so Tk's own cursor, kept wide, is
        the block: its colour costs a configure, which only the idle fade pays."""
        cw = self.char_width(font)
        t.configure(insertwidth=0, insertbackground=INK, insertofftime=0)   # the blink is ours
        t.tag_configure("caret", background=INK, foreground=PAPER)
        t.tag_configure("glow")
        try:
            t.tag_lower("caret", "sel")
            t.tag_lower("glow", "caret")
        except tk.TclError:
            pass
        state = {"job": None, "focus": False, "level": 1.0, "at": None, "width": 0,
                 "color": INK, "woke": 0.0}
        glow = {"job": None}

        def place():
            """Puts the block on the cursor; gives the cursor's index."""
            t.tag_remove("caret", "1.0", "end")
            i = t.index("insert")
            shown = state["focus"] and not t.tag_ranges("sel")
            width = cw if shown and t.compare(i, ">=", i.split(".")[0] + ".end") else 0
            if width != state["width"]:
                state["width"] = width
                t.configure(insertwidth=width)
            if shown and not width:
                t.tag_add("caret", i, i + "+1c")
            return i

        def shade(level):
            state["level"] = level
            bg = mix(PAPER, INK, level)
            if not state["width"]:
                t.tag_configure("caret", background=bg, foreground=mix(INK, PAPER, level))
            elif bg != state["color"]:
                state["color"] = bg
                t.configure(insertbackground=bg)

        def fade(to):
            start = state["level"]
            tween(t, state, CARET_FADE_MS, lambda k: shade(start + (to - start) * k),
                  lambda: rest(1 - to), ease_both)

        def rest(to):
            asleep = to == 0 and (time.perf_counter() - state["woke"]) * 1000 >= CARET_SLEEP_MS
            if not asleep:
                state["job"] = t.after(CARET_HOLD_MS, fade, to)

        def afterglow(was):
            t.tag_remove("glow", "1.0", "end")
            if AFTERGLOW_MS and t.compare(was, "<", was + " lineend"):  # a line end would fill the row
                t.tag_add("glow", was, was + "+1c")
                tween(t, glow, AFTERGLOW_MS,
                      lambda k: t.tag_configure("glow", background=mix(PAPER, INK, AFTERGLOW * (1 - k))),
                      lambda: t.tag_remove("glow", "1.0", "end"))

        def wake(_e=None):
            if not state["focus"] or not t.winfo_exists():
                return
            halt(t, state)
            was, state["at"] = state["at"], place()
            if was and was != state["at"] and not t.tag_ranges("sel"):
                afterglow(was)
            shade(1.0)
            state["woke"] = time.perf_counter()
            rest(0.0)

        def gained(_e=None):
            state["focus"], state["at"] = True, None
            wake()

        def lost(_e=None):
            state["focus"] = False
            halt(t, state)
            place()

        t.bind("<FocusIn>", gained, add="+")
        t.bind("<FocusOut>", lost, add="+")
        for ev in ("<KeyRelease>", "<ButtonRelease-1>", "<<Selection>>", "<B1-Motion>"):
            t.bind(ev, wake, add="+")
        self.carets.append((t, state))
        self.pendings.append((t, glow))

    def usable_mono(self, family):
        try:
            if family not in tkfont.families(self.root):
                return False, tr("is not installed")
            f = tkfont.Font(family=family, size=11)
            widths = {f.measure(ch) for ch in "imMW1."}
            if len(widths) != 1:
                return False, tr("is not monospaced")
            if f.measure("M") < 3:
                return False, tr("has no metrics")
        except tk.TclError:
            return False, tr("is unreadable")
        return True, ""

    def mono_families(self):
        out = []
        for fam in sorted(set(tkfont.families(self.root))):
            if fam.startswith("@"):
                continue
            ok, _ = self.usable_mono(fam)
            if ok:
                out.append(fam)
        return out

    # ------------------------------------------------------------ dados
    def reload(self):
        """Reads the base again and rebuilds the search text of each record --
        only for records whose timestamp changed since the last time."""
        self.data = load_json()
        cache = getattr(self, "_hay", {})
        fresh = {}
        makers = (("people", lambda r: haystack_person(r)),
                  ("entries", lambda r: haystack_entry(r, self.data)),
                  ("sources", lambda r: haystack_source(r, self.data)),
                  ("corpus", lambda r: haystack_metric(r, self.data)),
                  ("notes", lambda r: haystack_note(r)))
        cache, seen = note_cache(), {}
        for n in self.data["notes"]:
            n["_body"] = note_body(n)       # read again only when the file changed
            key = str(note_path(n)) if n.get("file") else ""
            seen[n["id"]] = tuple(cache[key][0]) if key in cache else None
        save_note_cache({str(note_path(n)) for n in self.data["notes"] if n.get("file")})
        for coll, make in makers:
            for r in self.data[coll]:
                key = (r["id"], stamp_of(r), seen.get(r["id"]) if coll == "notes" else None)
                h = cache.get(key)
                if h is None:
                    h = make(r)
                r["_h"] = fresh[key] = h
        self._hay = fresh
        if self.draft:
            self.data[coll_of(self.draft["id"])].append(self.draft)
        self.refresh_rail()
        self.refresh_list()
        if getattr(self, "mc", None) and self.shown == "metric":
            self.mc.map.redraw()
        self.timeline_soon()
        self.say(summary(self.data))

    def say(self, text):
        self.status.configure(text=text)

    def current(self):
        if not self.sel:
            return None
        return by_id(self.data).get(self.sel)

    def rec_kind(self, rec):
        return {"people": "person", "entries": "entry", "sources": "source",
                "corpus": "metric", "notes": "note"}[coll_of((rec or {}).get("id", ""))]

    def refresh_list_soon(self):
        """The list redraws 150 ms after the last keystroke, not on every one."""
        if self._q_job:
            try:
                self.root.after_cancel(self._q_job)
            except tk.TclError:
                pass
        self._q_job = self.root.after(150, self.search_changed)

    def search_changed(self):
        self._q_job = None
        self.refresh_list()
        self.refresh_rail()
        self.quick_update(fresh=True)

    def parse_query(self):
        """The search box, read with the operators of parse_search."""
        return parse_search(self.q.get())

    def field_ok(self, r, fields):
        return search_field_ok(r, fields)

    def query_base(self):
        """What the search text alone finds, per collection: the words, ^prefix,
        field operators and p:/v:/f:/c:, but none of the rail's filters."""
        return search_base(self.data, self.q.get())

    def matches(self):
        qscope = self.parse_query()[0]
        scope = qscope or self.scope
        base = self.query_base()
        out = []

        if scope in (None, "people"):
            for p in base["people"]:
                if self.tag and self.tag not in p.get("tags", []):
                    continue
                if self.viewmode in ("todo", "doing", "waiting") and \
                        not open_tasks(p, self.viewmode):
                    continue
                if self.viewmode == "untagged" and p.get("tags"):
                    continue
                if self.viewmode == "orgs" and not p.get("org"):
                    continue
                if self.date and not any(t["due"] == self.date for t in dated_tasks(p)):
                    continue
                if self.view_circle == "none" and p.get("circles"):
                    continue
                if self.view_circle not in (None, "none") and \
                        self.view_circle not in p.get("circles", []):
                    continue
                out.append(p)
        if scope in (None, "entries"):
            for e in base["entries"]:
                if self.view_kind and e["kind"] != self.view_kind:
                    continue
                if self.view_lang and e.get("lang") != self.view_lang:
                    continue
                if self.view_domain and self.view_domain not in e.get("domains", []):
                    continue
                out.append(e)
        if scope in (None, "sources"):
            for s in base["sources"]:
                if self.view_stype and (s.get("type") or "outro") != self.view_stype:
                    continue
                out.append(s)
        if scope in (None, "corpus"):
            for m in base["corpus"]:
                if self.view_htype and htype(m) != self.view_htype:
                    continue
                if self.view_system is not None and (m.get("system") or "") != self.view_system:
                    continue
                out.append(m)
        if scope in (None, "notes"):
            out.extend(base["notes"])
        out.sort(key=lambda r: sort_key(label_any(r, self.data) if coll_of(r["id"]) == "sources"
                                        else r["name"]))
        return out

    def row_text(self, r):
        """(title, subtitle) of a record in the list."""
        return list_row_text(r, self.data, self.date)

    def insert_row(self, r, loc):
        text, sub = self.row_text(r)
        self.list.insert("", "end", iid=r["id"], text=one_liner(text, 60),
                         values=(one_liner(sub, 60), loc), tags=("sub",))

    def filter_sig(self):
        return (self.q.get().strip(), self.scope, self.tag, self.viewmode, self.date,
                self.view_kind, self.view_lang, self.view_domain, self.view_stype,
                self.view_htype, self.view_circle, self.view_system)

    def refresh_list(self):
        """Without a search or filter, the list is the REGISTER: everything in
        number order, cancelled numbers in place, opening at the end (the newest).
        With a search or filter, it is the INDEX: what matches, alphabetically,
        each row with its number. Either way, the view only shows the rows that
        fit the window; the rest is on the following pages."""
        self._q_job = None
        sig = self.filter_sig()
        filtered = bool(any(sig[:-1]) or self.view_system is not None)
        if sig != self.page_sig:
            self.page_sig = sig
            self.top = 0 if filtered else None
            self.timeline_soon()
        total = sum(len(self.data[c]) for c in COLLS)
        if filtered:
            self.mode = "index"
            self.view = [("r", r) for r in self.matches()]
        else:
            self.mode = "register"
            live, loose = {}, []
            for c in COLLS:
                for r in self.data[c]:
                    if r.get("reg_n"):
                        live[r["reg_n"]] = r
                    else:
                        loose.append(r)
            gone = {d["reg_n"]: d for d in self.data.get("deleted", [])
                    if d.get("reg_n") and d["reg_n"] not in live}
            self.view = [("r", live[n]) if n in live else ("x", gone[n])
                         for n in sorted(set(live) | set(gone))]
            self.view += [("r", r) for r in loose]       # drafts, at the end
        self.view_num = {o["reg_n"]: i for i, (_, o) in enumerate(self.view)
                         if o.get("reg_n")}
        self.view_pos = {o["id"]: i for i, (k, o) in enumerate(self.view) if k == "r"}
        self.rows = self.rows_fit()
        if self.top is None:          # the end: the last full view
            self.top = max(0, len(self.view) - self.rows)
        self.top = max(0, min(self.top, len(self.view) - 1))
        shown = self.view[self.top:self.top + self.rows]
        self.list.delete(*self.list.get_children())
        for kind, o in shown:
            n = o.get("reg_n")
            if kind == "x":
                self.list.insert("", "end", iid=f"x:{n}",
                                 text=tr("cancelled · {name}", name=one_liner(o.get("name", ""), 40)),
                                 values=(tr("on {date}", date=(o.get("at") or "")[:10]), f"nº {n}"),
                                 tags=("cancel",))
            else:
                self.insert_row(o, f"nº {n}" if n else tr("new"))
        a, b = self.top + 1, self.top + len(shown)
        if self.mode == "register":
            nums = [o.get("reg_n") for _, o in shown if o.get("reg_n")]
            span = f"nº {nums[0]}–{nums[-1]}" if nums else tr("empty")
            self.page_lbl.configure(text=tr("REGISTER · {span}", span=span))
            self.count.configure(text=tr("{n} records", n=total))
        else:
            self.page_lbl.configure(
                text=tr("INDEX · {a}–{b} of {n}", a=a, b=b, n=len(self.view)) if shown
                else tr("INDEX · nothing found"))
            self.count.configure(text=tr("{n} of {total}", n=len(self.view), total=total))
        if self.sel and self.list.exists(self.sel):
            self.list.selection_set(self.sel)
        self.refresh_chips()

    def show_in_list(self, rid):
        """Moves the view to the record, if it is outside it."""
        if self.list.exists(rid):
            return
        i = self.view_pos.get(rid)
        if i is None:
            if self.mode == "register":       # a new draft: it sits at the end
                self.top = None
                self.refresh_list()
            return
        self.top = max(0, i - self.rows // 2)
        self.refresh_list()

    def set_locus(self, rec):
        if not rec:
            self.locus.configure(text="")
            return
        n = rec.get("reg_n")
        if not n:
            self.locus.configure(text=tr("NOT REGISTERED · GETS A NUMBER ON SAVE"))
            return
        text = tr("REGISTER Nº {n}    REGISTERED {stamp}", n=n, stamp=stamp_label(rec.get("reg")))
        if rec.get("reg_origem"):
            text += "  " + tr("(inferred: {origin})", origin=tr(
                REG_ORIGIN.get(rec["reg_origem"], rec["reg_origem"])))
        if rec.get("reg_n_anterior"):
            text += "  · " + tr("formerly nº {n}", n=rec["reg_n_anterior"])
        self.locus.configure(text=text)

    def refresh_rail(self):
        """The rail lists every category of the base, always; its numbers count
        what the current search finds, so typing shows at once where the
        matches are (another collection, a tag, a language...). Categories with
        nothing for the search are dimmed, not hidden."""
        r = self.rail
        out = []                        # (iid, text, values, tags), applied at the end
        data = self.data
        base = self.query_base()
        people, entries, sources, corpus = (base[c] for c in
                                            ("people", "entries", "sources", "corpus"))
        searching = bool(self.q.get().strip())

        def head(iid, text):
            out.append((iid, "", (), ("head",)))
            out.append((iid + "b", text, (), ("head",)))

        def item(iid, text, n, on, extra=()):
            tags = ("on",) if on else tuple(extra) + (("zero",) if searching and not n else ())
            out.append((iid, text, (n,), tags))

        out.append(("h0", tr("COLLECTIONS"), (), ("head",)))
        for coll in COLLS:
            item("s:" + coll, "  " + tr(COLL_LABEL[coll]), len(base[coll]), self.scope == coll,
                 ("scope",))

        if data["people"]:
            head("h1", tr("WORK"))
            for key, lab in (("todo", tr("to do")), ("doing", tr("in progress")),
                             ("waiting", tr("waiting on"))):
                item("v:" + key, "  " + lab, sum(1 for p in people if open_tasks(p, key)),
                     self.viewmode == key)
            item("v:untagged", "  " + tr("untagged"),
                 sum(1 for p in people if not p.get("tags")), self.viewmode == "untagged")
            if any(p.get("org") for p in data["people"]):
                item("v:orgs", "  " + tr("organizations"),
                     sum(1 for p in people if p.get("org")), self.viewmode == "orgs")
            all_days = sorted({t["due"] for p in data["people"] for t in dated_tasks(p)})
            if all_days:
                days = {}
                for p in people:
                    for t in dated_tasks(p):
                        days[t["due"]] = days.get(t["due"], 0) + 1
                head("h3", tr("CALENDAR"))
                today = TODAY()
                for day in all_days:
                    mark, flag = ((("late",), "! ") if day < today else
                                  (("today",), "> ") if day == today else ((), "  "))
                    item("d:" + day, flag + day, days.get(day, 0), self.date == day, mark)
            # Covey's circles, outermost first; a person can be in more than one
            head("h2c", tr("CIRCLES"))
            for c in CIRCLES:
                item("o:" + c, "  " + tr(c), sum(1 for p in people if c in p.get("circles", [])),
                     self.view_circle == c)
            item("o:none", "  " + tr("no circle"),
                 sum(1 for p in people if not p.get("circles")), self.view_circle == "none")
            all_tags = sorted({t for p in data["people"] for t in p.get("tags", []) if ":" not in t},
                              key=sort_key)
            if all_tags:
                tags = {}
                for p in people:
                    for t in p.get("tags", []):
                        tags[t] = tags.get(t, 0) + 1
                head("h2", tr("TAGS"))
                for t in all_tags:
                    item("t:" + t, "  " + t, tags.get(t, 0), self.tag == t)

        if data["entries"]:
            head("h4", tr("KIND"))
            for key, lab in (("concept", tr("concepts")), ("form", tr("forms"))):
                item("k:" + key, "  " + lab, sum(1 for e in entries if e["kind"] == key),
                     self.view_kind == key)
            all_langs = sorted({e["lang"] for e in data["entries"]
                                if e["kind"] == "form" and e.get("lang")}, key=sort_key)
            if all_langs:
                head("h5", tr("LANGUAGE"))
                for lang in all_langs:
                    item("l:" + lang, "  " + lang,
                         sum(1 for e in entries if e["kind"] == "form" and e.get("lang") == lang),
                         self.view_lang == lang)
            all_doms = sorted({d for e in data["entries"] for d in e.get("domains", [])},
                              key=sort_key)
            if all_doms:
                head("h6", tr("DOMAIN"))
                for d in all_doms:
                    item("m:" + d, "  " + d, sum(1 for e in entries if d in e.get("domains", [])),
                         self.view_domain == d)

        if data["sources"]:
            head("h7", tr("SOURCE TYPE"))
            for t in sorted({s.get("type") or "outro" for s in data["sources"]},
                            key=lambda t: sort_key(type_label(t))):
                item("y:" + t, "  " + type_label(t),
                     sum(1 for s in sources if (s.get("type") or "outro") == t),
                     self.view_stype == t)
        if data["corpus"]:
            head("h9", tr("HEALTH"))
            present = {htype(m) for m in data["corpus"]}
            for t in HEALTH_TYPES:
                if t in present:
                    item("u:" + t, "  " + tr(HEALTH_TYPE_LABEL[t]),
                         sum(1 for m in corpus if htype(m) == t), self.view_htype == t)
            head("h8", tr("SYSTEM"))
            for sname in sorted({m.get("system") or "" for m in data["corpus"]},
                                key=lambda x: sort_key(system_label(x))):
                item("z:" + sname, "  " + (system_label(sname) or tr("(no system)")),
                     sum(1 for m in corpus if (m.get("system") or "") == sname),
                     self.view_system == sname)
        self.apply_rail(out)

    def apply_rail(self, rows):
        """Puts the rows on the rail. While typing the categories stay the same and
        only their numbers and dimming change, so the items are updated in place
        (a rebuild would redraw the whole rail and lose its scroll position)."""
        r = self.rail
        if tuple(r.get_children()) != tuple(iid for iid, *_ in rows):
            top = r.yview()[0]
            r.delete(*r.get_children())
            for iid, text, values, tags in rows:
                r.insert("", "end", iid=iid, text=text, values=values, tags=tags)
            r.yview_moveto(top)
            self._rail_rows = {iid: rest for iid, *rest in rows}
            return
        old = getattr(self, "_rail_rows", {})
        for iid, text, values, tags in rows:
            if old.get(iid) != [text, values, tags]:
                r.item(iid, text=text, values=values, tags=tags)
        self._rail_rows = {iid: [text, values, tags] for iid, text, values, tags in rows}

    # ---- the filters in force, shown as chips above the list
    FACETS = (("tag", "people"), ("viewmode", "people"), ("date", "people"),
              ("view_circle", "people"), ("view_kind", "entries"), ("view_lang", "entries"),
              ("view_domain", "entries"), ("view_stype", "sources"), ("view_htype", "corpus"),
              ("view_system", "corpus"))

    def facet_label(self, attr, value):
        if attr == "tag":
            return tr("tag: {tag}", tag=value)
        if attr == "viewmode":
            return {"todo": tr("to do"), "doing": tr("in progress"), "waiting": tr("waiting on"),
                    "untagged": tr("untagged"), "orgs": tr("organizations")}.get(value, value)
        if attr == "view_circle":
            return tr("no circle") if value == "none" else tr(value)
        if attr == "view_kind":
            return tr("concepts") if value == "concept" else tr("forms")
        if attr == "view_stype":
            return type_label(value)
        if attr == "view_htype":
            return tr(HEALTH_TYPE_LABEL[value])
        if attr == "view_system":
            return system_label(value) or tr("(no system)")
        return value

    def drop_filter(self, attr):
        """Takes one filter away. A collection that only a filter had imposed
        (a tag implies people) goes with it; one picked in COLLECTIONS stays."""
        self.commit_if_dirty()
        if attr == "q":
            self.q.set("")
        elif attr == "scope":
            self.scope, self.scope_explicit = None, False
            self.clear_filters()
        elif attr == "all":
            self.q.set("")
            self.clear_filters()
            self.scope, self.scope_explicit = None, False
        else:
            setattr(self, attr, None)
            if not self.scope_explicit and all(getattr(self, a) is None for a, _ in self.FACETS):
                self.scope = None
        if self._q_job:
            try:
                self.root.after_cancel(self._q_job)
            except tk.TclError:
                pass
            self._q_job = None
        self.refresh_rail()
        self.refresh_list()

    def refresh_chips(self):
        """The bar of filters in force. Typing only changes the search chip's text,
        so the labels are kept and updated in place: rebuilding them (and packing
        the bar again) on every keystroke cost a full relayout of the list."""
        box = self.chips
        items = []
        q = self.q.get().strip()
        if q:
            items.append((tr("search: {q}", q=one_liner(q, 28)), "q"))
        if self.scope and self.scope_explicit:
            items.append((tr(COLL_LABEL[self.scope]), "scope"))
        for attr, _ in self.FACETS:
            value = getattr(self, attr)
            if value is not None and (value != "" or attr == "view_system"):
                items.append((self.facet_label(attr, value), attr))
        if len(items) > 1:
            items.append((tr("clear all"), "all"))
        shape = tuple(a for _, a in items)
        if shape != getattr(self, "_chip_shape", None):
            self._chip_shape = shape
            for w in box.winfo_children():
                w.destroy()
            for text, attr in items:
                lbl = tk.Label(box, bg=PAPER, fg=STAMP if attr != "all" else SOFT,
                               font=self.f_label, cursor="hand2", padx=6, pady=1,
                               highlightthickness=1, highlightbackground=RULE)
                lbl.pack(side="left", padx=(6, 0), pady=4)
                lbl.bind("<Button-1>", lambda e, a=attr: self.drop_filter(a))
            if items and not box.winfo_manager():
                box.pack(fill="x", before=self.list_head)
            elif not items and box.winfo_manager():
                box.pack_forget()
        for lbl, (text, attr) in zip(box.winfo_children(), items):
            text = ("× " if attr != "all" else "") + text
            if lbl.cget("text") != text:
                lbl.configure(text=text)

    def filter_system(self, sname):
        """A click on the map: filters the list by that system (again, removes the filter)."""
        self.commit_if_dirty()
        was = self.view_system
        self.clear_filters()
        self.view_system = None if was == sname else sname
        self.scope = "corpus"
        self.refresh_rail()
        self.refresh_list()
        if self.sel is None or self.rec_kind(self.current()) != "metric":
            self.show_corpus_blank()
        else:
            self.mc.map.set_current(self.view_system)

    def show_corpus_blank(self):
        """With no measurement open, the corpus card shows only the map."""
        self.blank_card()
        self.show_card("metric")
        self.mc.map.set_current(self.view_system)

    def clear_filters(self):
        self.tag = self.viewmode = self.date = self.view_circle = None
        self.scope_explicit = False
        self.view_kind = self.view_lang = self.view_domain = None
        self.view_stype = self.view_system = self.view_htype = None

    def on_rail(self, _event):
        sel = self.rail.selection()
        if not sel:
            return
        self.commit_if_dirty()
        iid = sel[0]
        key = iid[2:]
        if iid.startswith("s:"):
            self.clear_filters()
            self.scope = None if self.scope == key else key
            self.scope_explicit = self.scope is not None
        elif iid.startswith("v:"):
            was = self.viewmode
            self.clear_filters()
            self.viewmode = None if was == key else key
            self.scope = "people"
        elif iid.startswith("o:"):
            was = self.view_circle
            self.clear_filters()
            self.view_circle = None if was == key else key
            self.scope = "people"
        elif iid.startswith("t:"):
            was = self.tag
            self.clear_filters()
            self.tag = None if was == key else key
            self.scope = "people"
        elif iid.startswith("d:"):
            was = self.date
            self.clear_filters()
            self.date = None if was == key else key
            self.scope = "people"
        elif iid.startswith("k:"):
            was = self.view_kind
            self.clear_filters()
            self.view_kind = None if was == key else key
            self.scope = "entries"
        elif iid.startswith("l:"):
            was = self.view_lang
            self.clear_filters()
            self.view_lang = None if was == key else key
            self.scope = "entries"
        elif iid.startswith("m:"):
            was = self.view_domain
            self.clear_filters()
            self.view_domain = None if was == key else key
            self.scope = "entries"
        elif iid.startswith("y:"):
            was = self.view_stype
            self.clear_filters()
            self.view_stype = None if was == key else key
            self.scope = "sources"
        elif iid.startswith("u:"):
            was = self.view_htype
            self.clear_filters()
            self.view_htype = None if was == key else key
            self.scope = "corpus"
        elif iid.startswith("z:"):
            was = self.view_system
            self.clear_filters()
            self.view_system = None if was == key else key
            self.scope = "corpus"
        else:
            return
        self.rail.selection_remove(*self.rail.selection())
        self.refresh_rail()
        self.refresh_list()
        if self.scope == "corpus" and (self.sel is None
                                       or self.rec_kind(self.current()) != "metric"):
            self.show_corpus_blank()
        elif self.scope == "corpus":
            self.mc.map.set_current(self.view_system or (self.current() or {}).get("system"))

    def focus_list(self):
        self.list.focus_set()
        kids = self.list.get_children()
        if kids and not self.list.selection():
            self.list.selection_set(kids[0])

    def on_pick(self, _event):
        if self.busy:
            return
        sel = self.list.selection()
        if not sel or sel[0] == self.sel:
            return
        rid = sel[0]
        self.busy = True
        try:
            self.commit_if_dirty()
            if rid.startswith("x:"):
                self.show_cancelled(int(rid[2:]))
            elif self.list.exists(rid):
                self.open_record(rid)
            else:
                self.blank_card()
        finally:
            self.busy = False

    def blank_card(self):
        self.loading = True
        for c in self.cards.values():
            c.clear()
            c.enable(False)
        self.loading = False
        self.dirty = False
        self.sel = None
        self.set_locus(None)
        if getattr(self, "reader", None):
            self.reader.close(keep=False)

    def show_cancelled(self, n):
        """A cancelled number: the card stays empty and the header says what
        used to hold the number."""
        d = next((d for d in self.data.get("deleted", []) if d.get("reg_n") == n), None)
        self.blank_card()
        if d:
            self.locus.configure(
                text=tr("REGISTER Nº {n}    CANCELLED ON {at}  ·  {name}  ({id})", n=n,
                        at=(d.get("at") or "").replace("T", " "), name=d.get("name", ""),
                        id=d.get("id", "")))
            self.say(tr("Cancelled record: its history is in the log (Base › History)."))

    def open_record(self, rid):
        rec = by_id(self.data).get(rid)
        if not rec:
            return
        if self.reader.is_open and rid != self.reader.rid:
            self.reader.close()
        self.sel = rid
        self.loading = True
        kind = self.rec_kind(rec)
        self.show_card(kind, front=False)
        self.card.open(rec)
        self.set_locus(rec)
        for reset in self.undo_resets:
            try:
                reset()
            except Exception:
                pass
        self.show_in_list(rid)
        if self.list.exists(rid):
            self.list.selection_set(rid)
            self.list.see(rid)
        self.loading = False
        self.dirty = False
        self.refit_card()
        self.front_card()
        for view in (getattr(self, "graph", None), getattr(self, "monads", None)):
            if view and view.is_open():
                view.follow(rid)
        if self._dwell_job:
            self.root.after_cancel(self._dwell_job)
        self._dwell_job = self.root.after(DUST_DWELL_MS, lambda: self.dwell_done(rid))

    # ---- dust off: the record gone longest without a visit
    def dwell_done(self, rid):
        self._dwell_job = None
        if self.sel == rid:
            self.mark_seen(rid)

    def mark_seen(self, rid):
        """A visit to a record, written to this machine's file a moment later."""
        if not rid or rid.startswith("__"):
            return
        self.seen[rid] = self.seen_new[rid] = NOW()
        if not self._seen_job:
            self._seen_job = self.root.after(3000, self.flush_seen)

    def flush_seen(self):
        if self._seen_job:
            try:
                self.root.after_cancel(self._seen_job)
            except tk.TclError:
                pass
        self._seen_job = None
        if self.seen_new and seen_write(self.seen_new, keep=set(by_id(self.data))):
            self.seen_new = {}

    def dust_off(self):
        """Ctrl+D: opens the record gone longest without a visit -- opened or
        saved -- among those in the list: the whole register, or what the search
        and the filters leave (Ctrl+5 first: only the drafts). Each one opened
        goes to the back of the line, so pressing again goes through them all."""
        for rid, t in seen_read().items():          # the other machines' visits too
            if t > self.seen.get(rid, ""):
                self.seen[rid] = t
        pool = [o for k, o in getattr(self, "view", []) if k == "r"
                and not o["id"].startswith("__") and o["id"] != self.sel]
        if not pool:
            self.say(tr("Nothing to dust off in this list."))
            return "break"
        order = dust_order(pool, self.seen)
        rec = order[0]
        when = last_visit(rec, self.seen)[:10]
        cutoff = (datetime.now() - timedelta(days=DUST_OLD_DAYS)).isoformat(timespec="seconds")
        older = sum(1 for r in order[1:] if last_visit(r, self.seen) < cutoff)
        self.goto(rec["id"])
        if self.sel != rec["id"]:
            return "break"
        self.mark_seen(rec["id"])
        name = one_liner(label_any(rec, self.data), 50)
        said = (tr("Dust off · {name} · last visit {when}", name=name, when=when) if when
                else tr("Dust off · {name} · no visit recorded", name=name))
        if older:
            said += " · " + tr("{n} more in this list unvisited for over a month", n=older)
        self.say(said)
        return "break"

    # ---- the wide card's search: its results in a small list under it
    def find_index(self):
        """Ctrl+F: to the search; on the wide card its results show under it."""
        self.entry.focus_set()
        self.entry.select_range(0, "end")
        self.root.after_idle(self.quick_update)
        return "break"

    def quick_on(self):
        return self.quick is not None and bool(self.quick.winfo_manager())

    def quick_update(self, fresh=False):
        """Shows, or puts away, the small list: only on the wide card, with
        something searched, while the search has the keys."""
        try:
            focused = self.root.focus_get() is self.entry
        except (KeyError, tk.TclError):
            focused = False
        if not (self.wide and focused and self.q.get().strip()):
            self.quick_hide()
            return
        if fresh or not self.quick_on():
            self.quick_items = [o for k, o in getattr(self, "view", []) if k == "r"
                                and not o["id"].startswith("__")]
            self.quick_top = self.quick_cur = 0
        self.quick_draw()

    def quick_build(self):
        f = self.quick = tk.Frame(self.root, bg=PAPER, highlightthickness=1,
                                  highlightbackground=STAMP, highlightcolor=STAMP, bd=0)
        f.columnconfigure(0, weight=1)
        self.quick_rows = []
        notches = WheelNotches()

        def wheel(e):
            return wheel_turn(notches, e, lambda step: self.quick_move(step * 3))
        for seq in ("<MouseWheel>", "<Button-4>", "<Button-5>"):
            self.root.bind_class("KustosQuick", seq, wheel)
        bind_touchpad(lambda seq, fn: self.root.bind_class("KustosQuick", seq, fn), wheel)
        for i in range(QUICK_ROWS):
            row = tk.Frame(f, bg=PAPER, cursor="hand2")
            num = tk.Label(row, bg=PAPER, fg=FAINT, font=self.f_meta, anchor="e")
            title = tk.Label(row, bg=PAPER, fg=INK, font=self.f_row, anchor="w")
            subt = tk.Label(row, bg=PAPER, fg=SOFT, font=self.f_meta, anchor="w")
            num.pack(side="right", padx=(6, 10), pady=3)
            title.pack(side="left", padx=(10, 8), pady=3)
            subt.pack(side="left", fill="x", expand=True, pady=3)
            for w in (row, num, title, subt):
                w.bindtags(("KustosQuick",) + w.bindtags())
                w.bind("<Button-1>", lambda e, i=i: self.quick_open(self.quick_top + i))
                w.bind("<Motion>", lambda e, i=i: self.quick_point(self.quick_top + i))
            self.quick_rows.append((row, title, subt, num))
        self.quick_foot = tk.Label(f, bg=PAPER, fg=FAINT, font=self.f_label, anchor="w")
        self.quick_foot.bindtags(("KustosQuick",) + self.quick_foot.bindtags())
        self.quick_foot.grid(row=QUICK_ROWS, column=0, sticky="ew", padx=10, pady=(2, 4))

    def quick_draw(self):
        if self.quick is None:
            self.quick_build()
        items, top, cur = self.quick_items, self.quick_top, self.quick_cur
        for i, (row, title, subt, num) in enumerate(self.quick_rows):
            j = top + i
            if j >= len(items):
                row.grid_remove()
                continue
            r = items[j]
            text, sub = self.row_text(r)
            on = j == cur
            bg, fg = (SELBG, SELFG) if on else (PAPER, INK)
            row.configure(bg=bg)
            title.configure(text=one_liner(text, 46), bg=bg, fg=fg)
            subt.configure(text=one_liner(sub, 70), bg=bg, fg=fg if on else SOFT)
            num.configure(text=f"nº {r['reg_n']}" if r.get("reg_n") else "", bg=bg,
                          fg=fg if on else FAINT)
            row.grid(row=i, column=0, sticky="ew")
        if items:
            shown = f"{top + 1}–{min(top + QUICK_ROWS, len(items))} / {len(items)}"
            self.quick_foot.configure(text=shown + "   " + tr("↑ ↓ choose · Enter opens · Esc closes"))
        else:
            self.quick_foot.configure(text=tr("Nothing found."))
        self.quick_place()

    def quick_place(self):
        x = self.entry.winfo_rootx() - self.root.winfo_rootx()
        y = self.entry.winfo_rooty() - self.root.winfo_rooty() + self.entry.winfo_height() + 2
        self.quick.place(x=x, y=y, width=max(320, self.entry.winfo_width()))
        self.quick.lift()

    def quick_hide(self):
        if self.quick_on():
            self.quick.place_forget()

    def quick_move(self, step):
        """The highlight `step` rows on, the window of rows following it."""
        if not self.quick_items:
            return
        cur = max(0, min(len(self.quick_items) - 1, self.quick_cur + step))
        self.quick_cur = cur
        if cur < self.quick_top:
            self.quick_top = cur
        elif cur >= self.quick_top + QUICK_ROWS:
            self.quick_top = cur - QUICK_ROWS + 1
        self.quick_draw()

    def quick_point(self, j):
        if j != self.quick_cur and j < len(self.quick_items):
            self.quick_cur = j
            self.quick_draw()

    def quick_open(self, j):
        if not 0 <= j < len(self.quick_items):
            return "break"
        rid = self.quick_items[j]["id"]
        self.quick_hide()
        self.goto(rid)
        self.focus_card()
        return "break"

    def entry_key(self, step):
        """↓ ↑ PageDown PageUp Enter in the search: in the small list when it is
        there; otherwise ↓ and Enter go to the list, as always (on the wide
        card, where the list is hidden, they bring the small list back)."""
        if self.quick_on():
            return self.quick_open(self.quick_cur) if step == 0 else (self.quick_move(step), "break")[1]
        if self.wide:
            self.quick_update()
            return "break"
        if step >= 0:
            self.focus_list()
            return "break"
        return None

    def entry_escape(self):
        if self.quick_on() or self.wide:
            self.quick_hide()
            self.focus_card()
            return "break"
        return None

    def goto(self, rid):
        if rid not in by_id(self.data):
            self.say(tr("{id} does not exist.", id=rid))
            return
        self.commit_if_dirty()
        self.busy = True
        try:
            self.open_record(rid)
        finally:
            self.busy = False

    def mark_dirty(self, _event=None):
        if not self.loading:
            self.dirty = True
            self.flash("")

    # ------------------------------------------------------------ writing
    def clear_drafts(self):
        """Saves what is open and drops any empty new record left behind: all
        of a kind share one id, so the next would fail to enter the list."""
        self.commit_if_dirty()
        for coll in COLLS:
            self.data[coll] = [r for r in self.data[coll] if not r["id"].startswith("__")]
        self.draft = None

    def new_person(self, org=False):
        self.clear_drafts()
        self.draft = blank_person(self.q.get().strip(), org=org)
        self.draft["id"] = "__draft_p__"
        self.draft["_h"] = ""
        self.data["people"].append(self.draft)
        self.refresh_list()
        self.open_record("__draft_p__")
        self.pc.e_name.focus_set()
        self.say(tr("New organization. It only reaches the disk when saved.") if org
                 else tr("New person. It only reaches the disk when saved."))

    def new_entry(self, kind):
        self.clear_drafts()
        self.draft = {"id": "__draft_e__", "kind": kind, "name": "", "gloss": "",
                      "tags": [], "notes": "", "source": "", "links": [],
                      "domains": [], "updated": None, "_h": ""}
        if kind == "form":
            self.draft.update({"lang": "", "roman": "", "attested": "",
                               "status": "attested"})
        self.data["entries"].append(self.draft)
        self.refresh_list()
        self.open_record("__draft_e__")
        self.vc.e_name.focus_set()
        self.say(tr("New entry. The id is generated when saved with a name."))

    def new_source(self, raw=None):
        self.clear_drafts()
        raw = self.q.get().strip() if raw is None else raw
        self.draft = source_from_raw(raw) if raw else fix_source({"type": "livro"})
        self.draft["id"] = "__draft_s__"
        self.draft["_h"] = ""
        self.data["sources"].append(self.draft)
